        let fx = Fixture::new(scripts);
        let evidence = SkillEvidence::new();
        let mut gate = fx.gate.borrow_mut();
        let tools = Tools::new(
            &fx.registry,
            ToolEffectPorts::new(
                &fx.fs,
                fx.process.as_ref(),
                &evidence,
                Arc::new(NoResolver),
                Arc::new(NoHop),
                Arc::new(NoDuplex),
            ),
            CanonPath::new("/ws"),
        );
        let mut loop_ = TurnLoop::open(
            session(
                SessionState::default(),
                &fx.store,
                &fx.clock,
                &fx.sink,
                CancelToken::new(),
            ),
            model(&fx.generator, &mut gate),
            tools,
        )
        .with_goal(Some("verify artifact".into()), None);
        assert!(block_on(loop_.run("work")).unwrap().ok);
        assert_eq!(fx.generator.calls().len(), 5);
        assert_eq!(
            loop_.state().goal.unwrap().state,
            ego_core::goal::GoalState::Active
        );
