    #[test]
    fn goal_check_cancellation_settles_attempt_without_achievement_or_continuation() {
        // Catches: tool-less evaluator ignores cancellation and attests success after the operator stopped it.
        struct CancelCheck {
            fake: Arc<FakeGenerator>,
            cancel: CancelToken,
        }
        impl Generator for CancelCheck {
            fn ensure_expressible(
                &self,
                request: &GenRequest,
            ) -> Result<(), RequestExpressibilityError> {
                self.fake.ensure_expressible(request)
            }
            fn generate(&self, request: GenRequest, attempt: GenerationAttempt) -> AttemptStream {
                if serde_json::to_string(&request.messages)
                    .unwrap()
                    .contains("Independently check")
                {
                    self.cancel.cancel(CancelCause::User);
                }
                self.fake.generate(request, attempt)
            }
        }
        for automatic in [false, true] {
            let mut scripts = Vec::new();
            if automatic {
                scripts.push(arbitration_opening("pending"));
            } else {
                scripts.push(arbitration_tracking("pending", "tracking"));
            }
            scripts.extend([
                vec![AiEvent::Stop(StopReason::Stop)],
                goal_reply(true, "artifact verified"),
            ]);
            let fx = Fixture::new(scripts);
            let evidence = SkillEvidence::new();
            let registry = vec![RegisteredTool::Goal, RegisteredTool::Plan];
            let tools = Tools::from_registry(
                &registry,
                ToolEffectPorts::new(
                    &fx.fs,
                    fx.process.as_ref(),
                    &evidence,
                    Arc::new(NoResolver),
                    Arc::new(NoHop),
                    Arc::new(NoDuplex),
                ),
                CanonPath::new("/ws"),
            );
            let cancel = CancelToken::new();
            let generator = Arc::new(CancelCheck {
                fake: fx.generator.clone(),
                cancel: cancel.clone(),
            });
            let mut gate = fx.gate.borrow_mut();
            let runtime = model(&generator, &mut gate);
            let mut loop_ = TurnLoop::open(
                session(
                    SessionState::default(),
                    &fx.store,
                    &fx.clock,
                    &fx.sink,
                    cancel,
                ),
                runtime,
                tools,
            )
            .with_goal(
                (!automatic).then(|| "produce a verified artifact".into()),
                20,
            );
            block_on(loop_.run("work")).unwrap();
            let state = loop_.state();
            assert_eq!(state.plan.steps[0].status, StepStatus::Cancelled);
            assert_eq!(state.goal.unwrap().state, ego_core::goal::GoalState::Active);
            assert!(state.live_attempts.is_empty());
            assert_eq!(
                fx.store
                    .events()
                    .iter()
                    .filter(|event| matches!(event.kind, EventKind::AttemptSettled { .. }))
                    .count(),
                3
            );
            assert!(!fx.store.events().iter().any(|event| matches!(
                event.kind,
                EventKind::GoalContinuation { .. } | EventKind::WorklistContinuation { .. }
            )));
        }
    }

    /// Applies the native operator stop through the loop's own journal while
    /// the first main generation is in flight, like `/goal stop` while busy.
    struct OperatorStop {
        fake: Arc<FakeGenerator>,
        journal: Mutex<Option<SharedJournal<'static>>>,
        armed: AtomicBool,
    }
    impl Generator for OperatorStop {
        fn ensure_expressible(
            &self,
            request: &GenRequest,
        ) -> Result<(), RequestExpressibilityError> {
            self.fake.ensure_expressible(request)
        }
        fn generate(&self, request: GenRequest, attempt: GenerationAttempt) -> AttemptStream {
            if self.armed.swap(false, Ordering::SeqCst) {
                let journal = self.journal.lock().unwrap();
                let journal = journal.as_ref().unwrap();
                let goal = journal
                    .inspect(|state| state.goal.clone())
                    .unwrap()
                    .unwrap();
                journal
                    .cancel_goal(TurnId::new(), goal.id, ego_core::goal::GoalOwner::Operator)
                    .unwrap()
                    .unwrap();
            }
            self.fake.generate(request, attempt)
        }
    }

    /// Runs one admitted request whose goal the operator stops mid-reply.
    fn run_operator_stopped(
        scripts: Vec<Vec<AiEvent>>,
        pending_step: bool,
    ) -> (SessionState, Vec<DomainEvent>, usize) {
        let fx: &'static Fixture = Box::leak(Box::new(Fixture::new(scripts)));
        let mut seed = SessionState::default();
        if pending_step {
            let journal = SharedJournal::new(Journal::new(
                SessionId::new(),
                &fx.store,
                &fx.clock,
                &fx.sink,
                Producer::Main,
                SessionState::default(),
            ));
            journal
                .append(
                    TurnId::new(),
                    None,
                    None,
                    EventKind::PlanUpdated {
                        update: ego_core::plan::PlanUpdate::Replace {
                            steps: vec![ego_core::plan::PlanStep {
                                id: "pending-row".into(),
                                text: "unfinished independent work".into(),
                                status: StepStatus::Pending,
                                reason: None,
                            }],
                        },
                    },
                )
                .unwrap();
            seed = journal.inspect(Clone::clone).unwrap();
        }
        let generator = Arc::new(OperatorStop {
            fake: fx.generator.clone(),
            journal: Mutex::new(None),
            armed: AtomicBool::new(true),
        });
        let evidence: &'static SkillEvidence = Box::leak(Box::new(SkillEvidence::new()));
        let registry = vec![RegisteredTool::Goal, RegisteredTool::Plan];
        let tools = Tools::from_registry(
            &registry,
            ToolEffectPorts::new(
                &fx.fs,
                fx.process.as_ref(),
                evidence,
                Arc::new(NoResolver),
                Arc::new(NoHop),
                Arc::new(NoDuplex),
            ),
            CanonPath::new("/ws"),
        );
        let mut gate = fx.gate.borrow_mut();
        let runtime = model(&generator, &mut gate);
        let mut loop_ = TurnLoop::open(
            session(seed, &fx.store, &fx.clock, &fx.sink, CancelToken::new()),
            runtime,
            tools,
        )
        .with_goal(Some("preserve the original objective".into()), 20);
        *generator.journal.lock().unwrap() = Some(loop_.journal());
        block_on(loop_.run("work")).unwrap();
        generator.journal.lock().unwrap().take();
        (
            loop_.into_state().unwrap(),
            fx.store.events(),
            fx.generator.calls().len(),
        )
    }

    // Catches: after an operator stop the admitted request still runs its
    // pending worklist automatically (F1), or erases the worklist rows.
    #[test]
    fn operator_stop_pauses_worklist_continuation_and_keeps_every_row() {
        let (state, events, generations) = run_operator_stopped(
            vec![
                vec![AiEvent::Stop(StopReason::Stop)],
                vec![AiEvent::Stop(StopReason::Stop)],
                vec![AiEvent::Stop(StopReason::Stop)],
            ],
            true,
        );
        assert_eq!(
            generations, 1,
            "automatic worklist turn after operator stop"
        );
        assert!(!events.iter().any(|event| matches!(
            event.kind,
            EventKind::GoalContinuation { .. } | EventKind::WorklistContinuation { .. }
        )));
        assert_eq!(state.plan.steps.len(), 1);
        assert_eq!(state.plan.steps[0].status, StepStatus::Pending);
        let goal = state.goal.unwrap();
        assert_eq!(goal.state, ego_core::goal::GoalState::Cancelled);
        assert_eq!(goal.objective, "preserve the original objective");
    }

    // Catches: the still-running reply recreates an automatic goal right after
    // the operator stopped it (F3).
    #[test]
    fn operator_stop_refuses_automatic_goal_recreation_from_the_same_request() {
        let (state, events, _) = run_operator_stopped(
            vec![
                automatic_goal_call("recreate-after-stop", "restart the same work"),
                vec![AiEvent::Stop(StopReason::Stop)],
                goal_reply(true, "must not run"),
            ],
            false,
        );
        let goal = state.goal.unwrap();
        assert_eq!(goal.state, ego_core::goal::GoalState::Cancelled);
        assert_eq!(goal.objective, "preserve the original objective");
        assert_eq!(
            events
                .iter()
                .filter(|event| matches!(event.kind, EventKind::GoalSet { .. }))
                .count(),
            1
        );
        let refused = events
            .iter()
            .find_map(|event| match &event.kind {
                EventKind::ToolCallCompleted { ok, result } => Some((*ok, result.model_text())),
                _ => None,
            })
            .unwrap();
        assert!(!refused.0, "{}", refused.1);
        assert!(
            refused.1.contains("operator stopped automatic work"),
            "{}",
            refused.1
        );
    }

