    // Catches: a live child wake duplicates work, an explicit wake while still
    // running spins, or verified completion is confused with an active wait.
    #[cfg(unix)]
    #[test]
    fn arbitration_real_background_completion_reaches_both_mechanisms_once() {
        struct LiveCompletion(Mutex<(std::process::Child, bool)>);
        impl ego_core::mcp::McpTaskPort for LiveCompletion {
            fn started(&self, _: ego_core::mcp::McpTaskTicket, _: &ego_core::mcp::McpTaskStart) {}
            fn cancel_all<'a>(&'a self, _: ToolEffectPorts<'a>) -> BoxFuture<'a, ()> {
                Box::pin(async move {
                    let mut job = self.0.lock().unwrap();
                    if job.0.try_wait().unwrap().is_none() {
                        job.0.kill().unwrap();
                        job.0.wait().unwrap();
                    }
                })
            }
            fn refresh<'a>(
                &'a self,
                _: ToolEffectPorts<'a>,
            ) -> BoxFuture<'a, Result<Vec<ego_core::mcp::McpTaskSettlement>, String>> {
                Box::pin(async move {
                    use std::io::Read as _;
                    let mut job = self.0.lock().unwrap();
                    if job.1 {
                        return Ok(Vec::new());
                    }
                    let Some(status) = job.0.try_wait().map_err(|e| e.to_string())? else {
                        return Ok(Vec::new());
                    };
                    assert!(status.success());
                    let mut output = String::new();
                    job.0
                        .stdout
                        .take()
                        .unwrap()
                        .read_to_string(&mut output)
                        .unwrap();
                    job.1 = true;
                    Ok(vec![format!("background completed: {output}").into()])
                })
            }
        }
        impl Drop for LiveCompletion {
            fn drop(&mut self) {
                let job = self.0.get_mut().unwrap();
                if job.0.try_wait().unwrap().is_none() {
                    let _ = job.0.kill();
                    let _ = job.0.wait();
                }
            }
        }
        let child = std::process::Command::new("/bin/sh")
            .args(["-c", "cat >/dev/null; printf 'artifact-ready'"])
            .stdin(std::process::Stdio::piped())
            .stdout(std::process::Stdio::piped())
            .stderr(std::process::Stdio::piped())
            .spawn()
            .unwrap();
        let tasks = Arc::new(LiveCompletion(Mutex::new((child, false))));
        let fx = Fixture::new(vec![
            arbitration_tracking("pending", "tracking"),
            vec![AiEvent::Stop(StopReason::Stop)],
            waiting_goal_reply("live child is running; no independent work is ready"),
            vec![AiEvent::Stop(StopReason::Stop)],
            waiting_goal_reply("live child is still running"),
            arbitration_tracking("completed", "finish"),
            vec![AiEvent::Stop(StopReason::Stop)],
            goal_reply(
                true,
                "artifact independently verified after the live child exited",
            ),
        ]);
        with_waiting_goal(&fx, Some(tasks.clone()), |loop_| {
            assert!(block_on(loop_.run("Implement and verify")).unwrap().ok);
            assert_eq!(fx.generator.calls().len(), 3);
            assert!(block_on(loop_.continue_checkpoint()).unwrap().ok);
            assert_eq!(fx.generator.calls().len(), 5);
            assert_eq!(
                loop_.state().goal.unwrap().state,
                ego_core::goal::GoalState::Active
            );
            {
                let mut job = tasks.0.lock().unwrap();
                drop(job.0.stdin.take());
                assert!(job.0.wait().unwrap().success());
            }
            assert!(block_on(loop_.continue_checkpoint()).unwrap().ok);
            let state = loop_.state();
            assert_eq!(state.plan.steps[0].status, StepStatus::Completed);
            let goal = state.goal.unwrap();
            assert_eq!(goal.state, ego_core::goal::GoalState::Achieved);
            assert!(goal.achievement_evidence.is_some());
            let calls = fx.generator.calls();
            assert_eq!(calls.len(), 8);
            assert!(calls[5].messages.messages().iter().any(|message| {
                message_text(message).contains("background completed: artifact-ready")
            }));
            let events = fx.store.events();
            assert_eq!(events.iter().filter(|e| matches!(&e.kind, EventKind::McpTaskResultDelivered { text, .. } if text == "background completed: artifact-ready")).count(), 1);
            assert!(!events.iter().any(|e| matches!(
                e.kind,
                EventKind::GoalContinuation { .. } | EventKind::WorklistContinuation { .. }
            )));
            assert_eq!(SessionState::replay(events).plan, state.plan);
        });
    }

    #[derive(Default)]
    struct MemoryFile(std::sync::Mutex<Option<String>>);

    impl ego_core::memory::MemoryStore for MemoryFile {
        fn location(&self) -> String {
            "/home/.ego/memory/ws.md".into()
        }
        fn read(&self) -> Result<Option<String>, ego_core::memory::MemoryError> {
            Ok(self.0.lock().unwrap().clone())
        }
        fn write(&self, text: &str) -> Result<(), ego_core::memory::MemoryError> {
            *self.0.lock().unwrap() = Some(text.to_owned());
            Ok(())
        }
    }

    #[test]
    fn memory_tool_writes_in_default_mode_and_plan_mode_refuses() {
        // Catches: plan mode lets the model change user memory, or a memory
        // write leaves no tool result in the transcript.
        for (mode, written) in [(Mode::Plan, None), (Mode::Default, Some("- use mbx\n"))] {
            let mut fx = Fixture::new(vec![
                vec![
                    AiEvent::ToolCall {
                        call_id: "memory-1".into(),
                        name: "memory".into(),
                        args: r#"{"action":"add","entry":"use mbx"}"#.into(),
                    },
                    AiEvent::Stop(StopReason::ToolUse),
                ],
                vec![AiEvent::Stop(StopReason::Stop)],
            ]);
            fx.set_mode(mode);
            let store = Arc::new(MemoryFile::default());
            let evidence = SkillEvidence::new();
            let registry = vec![RegisteredTool::Memory(store.clone())];
            let tools = Tools::from_registry(
                &registry,
                ToolEffectPorts::new(
                    &fx.fs,
                    fx.process.as_ref(),
                    &evidence,
                    Arc::new(NoResolver),
                    Arc::new(NoHop),
                    Arc::new(NoDuplex),
                ),
                CanonPath::new("/ws"),
            );
            let mut gate = fx.gate.borrow_mut();
            let mut runtime = model(&fx.generator, &mut gate);
            runtime.policy_source = fx.policy_source.clone();
            let mut loop_ = TurnLoop::open(
                session(
                    SessionState::default(),
                    &fx.store,
                    &fx.clock,
                    &fx.sink,
                    CancelToken::new(),
                ),
                runtime,
                tools,
            );
            block_on(loop_.run("remember")).unwrap();
            assert_eq!(store.0.lock().unwrap().as_deref(), written, "{mode:?}");
            let state = loop_.state();
            let call = state
                .items
                .values()
                .find(|item| item.kind == ItemKind::ToolCall)
                .expect("the memory call is in the transcript");
            let text = tool_result_text(call);
            if written.is_some() {
                assert!(text.contains("memory updated"), "{text}");
            } else {
                assert!(text.contains("plan mode"), "{text}");
            }
        }
    }

    #[test]
    fn failed_tool_diagnostic_does_not_leak_known_secret_to_model_or_log() {
        // Catches: execution or preparation error-to-result conversion bypasses disclosure masking.
        const SECRET: &str = "critic-auth-token-274";
        struct DiagnosticTool {
            fail_prepare: bool,
        }

        impl TypedTool for DiagnosticTool {
            type Params = ReadParams;

            fn name(&self) -> &str {
                "read"
            }

            fn description(&self) -> &str {
                "reports a failed read diagnostic"
            }

            fn prepare_typed(
                &self,
                params: ReadParams,
                ctx: &PrepareCtx<'_>,
            ) -> Result<PreparedCall, ToolError> {
                if self.fail_prepare {
                    return Err(ToolError::InvalidParams(format!(
                        "credential rejected: {SECRET}"
                    )));
                }
                FakeReadTool.prepare_typed(params, ctx)
            }

            fn execute<'a, 'io>(
                &'a self,
                _call: PreparedCall,
                _io: &'a dyn GuardedIo<'io>,
            ) -> BoxFuture<'a, Result<ToolResult, ToolError>>
            where
                'io: 'a,
            {
                Box::pin(futures::future::ready(Err(ToolError::InvalidParams(
                    format!("credential rejected: {SECRET}"),
                ))))
            }
        }

        for fail_prepare in [false, true] {
            let mut fx = Fixture::new(vec![
                vec![
                    AiEvent::ToolCall {
                        call_id: "diagnostic".to_owned(),
                        name: "read".to_owned(),
                        args: r#"{"path":"/ws/input"}"#.to_owned(),
                    },
                    AiEvent::Stop(StopReason::ToolUse),
                ],
                vec![AiEvent::Stop(StopReason::Stop)],
            ]);
            fx.registry = vec![Arc::new(Typed(DiagnosticTool { fail_prepare }))];
            fx.fs.file("/ws/input", "input");
            let mut budget = fx.gate.borrow_mut();
            let tools = Tools::new(
                &fx.registry,
                ToolEffectPorts::new(
                    &fx.fs,
                    fx.process.as_ref(),
                    &fx.evidence,
                    Arc::new(NoResolver),
                    Arc::new(NoHop),
                    Arc::new(NoDuplex),
                )
                .with_secret_values(ego_core::secrets::SecretValues::new([SECRET
                    .as_bytes()
                    .to_vec()])),
                CanonPath::new("/ws"),
            );
            let mut turn = TurnLoop::open(
                session(
                    SessionState::default(),
                    &fx.store,
                    &fx.clock,
                    &fx.sink,
                    CancelToken::new(),
                ),
                model_for(&fx, &fx.generator, &mut budget),
                tools,
            );
            let outcome = block_on(turn.run("read the input")).expect("turn completes");
            assert_eq!(outcome.exit_reason, ExitReason::Completed);
            let events = fx.store.events();
            let diagnostic = events
                .iter()
                .find_map(|event| match &event.kind {
                    EventKind::ToolCallCompleted { ok: false, result } => Some(result.model_text()),
                    _ => None,
                })
                .expect("failed tool result is durable");
            let calls = fx.generator.calls();
            assert_eq!(calls.len(), 2, "the error is fed back to the model");
            let request = serde_json::to_string(&calls[1]).expect("serialize model request");
            assert!(
                !diagnostic.contains(SECRET) && !request.contains(SECRET),
                "failed diagnostic leaked known secret (prepare={fail_prepare}): log={diagnostic}; model={request}"
            );
            assert!(diagnostic.contains("[REDACTED]"));
        }
    }

    /// Every `seq` in the log, in the order it was written.
    fn seqs_of(fx: &Fixture) -> Vec<Seq> {
        fx.store.events().iter().map(|ev| ev.env.seq).collect()
    }

    /// `n` sequence values counted from the first one. `Seq` has no accessor
    /// on purpose — it is an ordering, not a number — so the expectation is
    /// built the same way the journal builds it.
    fn counting_from_one(n: usize) -> Vec<Seq> {
        let mut seq = Seq::ZERO;
        (0..n).map(|_| seq.next()).collect()
    }

    fn usage() -> Usage {
        tokens(100, 0, 0, 20)
    }

    fn tokens(uncached_input: u64, cache_read: u64, cache_write: u64, output: u64) -> Usage {
        Usage {
            uncached_input_tokens: uncached_input,
            cache_read_tokens: cache_read,
            cache_write_tokens: cache_write,
            cache_write_extended_tokens: 0,
            output_tokens: output,
            web_search_requests: 0,
            reasoning_tokens: None,
        }
    }

    #[test]
