    // Catches: text after a tool call in one generation writes the message
    // item's `AssistantMessage` twice (partial, then full), so a host that
    // appends every `item_completed` shows the narration twice (story 842).
    #[test]
    fn text_around_a_tool_call_completes_its_message_once_with_the_full_text() {
        let fx = Fixture::new(vec![
            vec![
                AiEvent::TextDelta {
                    text: "Let me read it.".to_string(),
                },
                AiEvent::ToolCall {
                    call_id: "call_1".to_string(),
                    name: "read".to_string(),
                    args: r#"{"path":"/ws/a"}"#.to_string(),
                },
                AiEvent::TextDelta {
                    text: " Then I answer.".to_string(),
                },
                AiEvent::Stop(StopReason::ToolUse),
            ],
            vec![AiEvent::Stop(StopReason::Stop)],
        ])
        .with_read_tool();

        let (reason, ok, _) = run(&fx, SessionState::default(), "read it");

        assert_eq!(reason, ExitReason::Completed);
        assert!(ok);
        let completions = |events: Vec<PublicEvent>| -> Vec<(ItemId, String)> {
            events
                .into_iter()
                .filter_map(|event| match event {
                    PublicEvent::ItemCompleted {
                        kind: ego_core::public::ItemKind::AgentMessage,
                        item,
                        text,
                        ..
                    } => Some((item, text.unwrap_or_default())),
                    _ => None,
                })
                .collect()
        };
        // The durable log is what `ego export --format transcript` projects.
        let durable = completions(
            fx.store
                .events()
                .iter()
                .filter_map(ego_core::public::project_public)
                .collect(),
        );
        let live = completions(fx.sink.events());
        for (surface, completed) in [("durable", &durable), ("live", &live)] {
            assert_eq!(
                completed
                    .iter()
                    .map(|(_, text)| text.as_str())
                    .collect::<Vec<_>>(),
                ["Let me read it. Then I answer."],
                "{surface} completions"
            );
        }
        assert_eq!(durable[0].0, live[0].0);
        let resumed = SessionState::replay(fx.store.events());
        let (conversation, _) = conversation_from(&resumed).expect("a resumed history rebuilds");
        let assistant = conversation
            .messages()
            .iter()
            .find(|message| message.role == Role::Assistant)
            .expect("the generation is in the history");
        assert!(
            matches!(
                assistant.content.as_slice(),
                [ContentBlock::Text { text }, ContentBlock::ToolUse { .. }]
                    if text == "Let me read it. Then I answer."
            ),
            "{:?}",
            assistant.content
        );
    }

    // Catches: the loop guard's warning opens its item before the open
    // narration has a durable record, so the narration sorts after the
    // warning in a resumed history (story 842).
    #[test]
    fn narration_keeps_its_place_ahead_of_a_loop_guard_warning() {
        let scripts = (0..7)
            .map(|index| {
                vec![
                    AiEvent::TextDelta {
                        text: format!("Polling {index}."),
                    },
                    AiEvent::ToolCall {
                        call_id: format!("cycle-{index}"),
                        name: "read".to_string(),
                        args: json!({"path":"/ws/status.txt"}).to_string(),
                    },
                    AiEvent::Stop(StopReason::ToolUse),
                ]
            })
            .chain([vec![AiEvent::Stop(StopReason::Stop)]])
            .collect();
        let fx = Fixture::new(scripts).with_read_tool();
        fx.fs.file("/ws/status.txt", "pending");

        let (reason, ok, _) = run(&fx, SessionState::default(), "poll seven times");

        assert_eq!(reason, ExitReason::Completed);
        assert!(ok);
        let resumed = SessionState::replay(fx.store.events());
        let mut items: Vec<_> = resumed.items.values().collect();
        items.sort_by_key(|item| item.seq);
        let warning = items
            .iter()
            .position(|item| {
                item.kind == ItemKind::HostContext && item.text.contains("Tool loop warning")
            })
            .expect("the loop guard warned");
        let around: Vec<_> = items[warning - 1..=warning + 1]
            .iter()
            .map(|item| (item.kind, item.text.starts_with("Polling")))
            .collect();
        assert_eq!(
            around,
            [
                (ItemKind::Assistant, true),
                (ItemKind::HostContext, false),
                (ItemKind::ToolCall, false),
            ]
        );
    }

