        fn native_workspace() -> CanonPath {
            if cfg!(windows) {
                CanonPath::new(r"C:\ws")
            } else {
                CanonPath::new("/ws")
            }
        }

        enum ResolutionStep {
            Ready(Box<Result<GenerationProfile, GenerationModelError>>),
            Pending,
        }

        pub(super) struct ScriptedGenerationSource {
            steps: Mutex<VecDeque<ResolutionStep>>,
            resolved: Mutex<Vec<GenerationRole>>,
            ready: Option<Mutex<Option<futures::channel::oneshot::Sender<()>>>>,
            trace: Option<GenerationTrace>,
        }

        #[derive(Clone, Default)]
        pub(super) struct GenerationTrace {
            pub(super) requests: Arc<Mutex<Vec<GenRequest>>>,
            steps: Arc<Mutex<Vec<String>>>,
            pub(super) timeline: Arc<Mutex<Vec<String>>>,
        }

        struct RecordingGenerator {
            inner: FakeGenerator,
            trace: GenerationTrace,
            expressibility: Result<(), String>,
        }

        impl Generator for RecordingGenerator {
            fn ensure_expressible(
                &self,
                _request: &GenRequest,
            ) -> Result<(), RequestExpressibilityError> {
                match &self.expressibility {
                    Ok(()) => Ok(()),
                    Err(message) => Err(RequestExpressibilityError::new(message.clone())),
                }
            }

            fn generate(&self, request: GenRequest, attempt: GenerationAttempt) -> AttemptStream {
                self.trace.requests.lock().unwrap().push(request.clone());
                self.trace
                    .steps
                    .lock()
                    .unwrap()
                    .push(format!("generate:{}", request.model));
                self.trace.timeline.lock().unwrap().push("provider".into());
                self.inner.generate(request, attempt)
            }
        }

        impl ScriptedGenerationSource {
            pub(super) fn new(
                profiles: impl IntoIterator<Item = Result<GenerationProfile, GenerationModelError>>,
            ) -> Self {
                Self {
                    steps: Mutex::new(
                        profiles
                            .into_iter()
                            .map(|profile| ResolutionStep::Ready(Box::new(profile)))
                            .collect(),
                    ),
                    resolved: Mutex::new(Vec::new()),
                    ready: None,
                    trace: None,
                }
            }

            fn pending_with_signal_at(
                mut self,
                index: usize,
            ) -> (Self, futures::channel::oneshot::Receiver<()>) {
                let (sender, receiver) = futures::channel::oneshot::channel();
                let mut steps = self.steps.lock().unwrap();
                assert!(index <= steps.len());
                steps.insert(index, ResolutionStep::Pending);
                drop(steps);
                self.ready = Some(Mutex::new(Some(sender)));
                (self, receiver)
            }

            fn pending_with_signal(self) -> (Self, futures::channel::oneshot::Receiver<()>) {
                self.pending_with_signal_at(0)
            }

            pub(super) fn with_trace(mut self, trace: GenerationTrace) -> Self {
                self.trace = Some(trace);
                self
            }

            fn roles(&self) -> Vec<GenerationRole> {
                self.resolved.lock().unwrap().clone()
            }
        }

        fn profile_with_settings(
            slug: &str,
            script: Vec<AiEvent>,
            trace: &GenerationTrace,
            output_ceiling: Option<u64>,
            context_ceiling: Option<u64>,
            thinking: ThinkingLevel,
            parallel_tool_calls: bool,
        ) -> GenerationProfile {
            profile_with_expressibility(
                slug,
                script,
                trace,
                ProfileSettings {
                    output_ceiling,
                    context_ceiling,
                    thinking,
                    parallel_tool_calls,
                },
                Ok(()),
            )
        }

        struct ProfileSettings {
            output_ceiling: Option<u64>,
            context_ceiling: Option<u64>,
            thinking: ThinkingLevel,
            parallel_tool_calls: bool,
        }

        fn profile_with_expressibility(
            slug: &str,
            script: Vec<AiEvent>,
            trace: &GenerationTrace,
            settings: ProfileSettings,
            expressibility: Result<(), String>,
        ) -> GenerationProfile {
            let mut capabilities = caps();
            capabilities.max_context_tokens = settings.context_ceiling;
            capabilities.max_output_tokens = settings.output_ceiling;
            capabilities.supports_parallel_tool_calls = settings.parallel_tool_calls;
            GenerationProfile {
                output_limit: None,
                identity: ego_core::config::ModelRef(slug.to_string()),
                request_model: slug.split_once('/').unwrap().1.to_string(),
                thinking: settings.thinking,
                generator: Arc::new(RecordingGenerator {
                    inner: FakeGenerator::new(vec![script]),
                    trace: trace.clone(),
                    expressibility,
                }),
                capabilities,
                metering: metering(),
                pricing_unavailable: None,
                rates: Some(rates()),
            }
        }

        fn refusing_profile(
            slug: &str,
            judge: bool,
            script: Vec<AiEvent>,
            trace: &GenerationTrace,
            output_ceiling: Option<u64>,
        ) -> GenerationProfile {
            profile_with_expressibility(
                slug,
                script,
                trace,
                ProfileSettings {
                    output_ceiling,
                    context_ceiling: Some(8_192),
                    thinking: if judge {
                        ThinkingLevel::Off
                    } else {
                        ThinkingLevel::High
                    },
                    parallel_tool_calls: false,
                },
                Err("the selected wire cannot encode this request".into()),
            )
        }

        pub(super) fn profile(
            slug: &str,
            judge: bool,
            script: Vec<AiEvent>,
            trace: &GenerationTrace,
            output_ceiling: Option<u64>,
        ) -> GenerationProfile {
            profile_with_settings(
                slug,
                script,
                trace,
                output_ceiling,
                Some(8_192),
                if judge || output_ceiling == Some(1_024) {
                    ThinkingLevel::Off
                } else {
                    ThinkingLevel::High
                },
                output_ceiling == Some(2_048),
            )
        }

        fn judge_context() -> JudgeContext {
            JudgeContext {
                confinement: RunConfinement::new(Confinement::Workspace, false, native_workspace())
                    .unwrap(),
                exec_caps: ExecCaps::READ_SCOPED.union(ExecCaps::WRITE_SCOPED),
            }
        }

        impl GenerationModelSource for ScriptedGenerationSource {
            fn resolve<'a>(
                &'a self,
                request: GenerationModelRequest,
            ) -> BoxFuture<'a, Result<GenerationProfile, GenerationModelError>> {
                let role = request.role();
                self.resolved.lock().unwrap().push(role);
                if let Some(trace) = &self.trace {
                    trace
                        .steps
                        .lock()
                        .unwrap()
                        .push(format!("resolve:{role:?}"));
                    trace.timeline.lock().unwrap().push("model_resolve".into());
                }
                let step = self
                    .steps
                    .lock()
                    .unwrap()
                    .pop_front()
                    .expect("the scripted source has one step per boundary");
                if matches!(step, ResolutionStep::Pending) {
                    if let Some(ready) = &self.ready
                        && let Some(sender) = ready.lock().unwrap().take()
                    {
                        let _ = sender.send(());
                    }
                    return Box::pin(futures::future::pending());
                }
                let ResolutionStep::Ready(result) = step else {
                    unreachable!("pending steps return above");
                };
                Box::pin(futures::future::ready(*result))
            }
        }

        fn profile_with_carryover(
            slug: &str,
            script: Vec<AiEvent>,
            trace: &GenerationTrace,
            carryover: ReasoningCarryover,
            dialect: Option<&str>,
        ) -> GenerationProfile {
            let mut profile = profile(slug, false, script, trace, Some(1_024));
            profile.capabilities.reasoning_carryover = carryover;
            profile.capabilities.reasoning_state_dialect = dialect.map(str::to_owned);
            profile
        }

        // Regression fixtures below use actual durable tool completion replay,
        // blob hydration, captured model preflight, and provider dispatch.
        const PNG_1X1: &[u8] = &[
            137, 80, 78, 71, 13, 10, 26, 10, 0, 0, 0, 13, 73, 72, 68, 82, 0, 0, 0, 1, 0, 0, 0, 1,
            8, 4, 0, 0, 0, 181, 28, 12, 2, 0, 0, 0, 11, 73, 68, 65, 84, 120, 218, 99, 100, 248, 15,
            0, 1, 5, 1, 1, 39, 24, 227, 102, 0, 0, 0, 0, 73, 69, 78, 68, 174, 66, 96, 130,
        ];

        fn image_profile(
            slug: &str,
            vision: bool,
            script: Vec<AiEvent>,
            trace: &GenerationTrace,
        ) -> GenerationProfile {
            use ego_core::generator::capabilities::{ImageInputSupport, ImageLimits};
            use ego_core::generator::types::ImageMediaType;
            let mut p = profile(slug, false, script, trace, Some(1_024));
            p.capabilities.image_input = if vision {
                ImageInputSupport::Supported(
                    ImageLimits::new(
                        BTreeSet::from([ImageMediaType::Png]),
                        None,
                        None,
                        None,
                        None,
                        None,
                        None,
                    )
                    .unwrap(),
                )
            } else {
                ImageInputSupport::Unsupported
            };
            p
        }
        fn image_seed(evidence: &SkillEvidence, native: bool) -> SessionState {
            SessionState::replay(image_seed_events(evidence, native))
        }

        fn image_seed_events(evidence: &SkillEvidence, native: bool) -> Vec<DomainEvent> {
            use ego_core::generator::types::{ImageMediaType, ImageRef};
            use ego_core::store::blob::BlobStore;
            let mut writer = evidence.blobs.begin().unwrap();
            writer.append(PNG_1X1).unwrap();
            let image = ImageRef::new(writer.commit().unwrap(), ImageMediaType::Png, 1, 1).unwrap();
            let mut events = Vec::new();
            let mut seq = Seq::ZERO;
            let item = ItemId::new();
            let turn = TurnId::new();
            let kinds = if native {
                vec![EventKind::UserPrompt {
                    text: "native image".into(),
                    images: vec![image],
                    audio: vec![],
                    queued_prompt: None,
                }]
            } else {
                vec![
                    EventKind::ToolCallStarted {
                        name: "read".into(),
                        args: "{}".into(),
                        call_id: Some("image-read".into()),
                    },
                    EventKind::ToolCallCompleted {
                        ok: true,
                        result: ToolResult::builtin("sibling coordinates x=11,y=12")
                            .with_images(vec![image]),
                    },
                ]
            };
            for kind in kinds {
                events.push(DomainEvent {
                    env: Envelope {
                        seq: seq.next(),
                        id: EventId::new(),
                        turn,
                        item: Some(item),
                        parent: None,
                        ts: Timestamp::from_millis(0),
                        producer: Producer::Main,
                    },
                    kind,
                });
            }
            events
        }
        fn run_image_profiles(
            fx: &Fixture,
            state: SessionState,
            evidence: &SkillEvidence,
            source: Arc<ScriptedGenerationSource>,
            fallback: bool,
        ) -> (ExitReason, bool, SessionState) {
            run_image_profiles_mode(fx, state, evidence, source, fallback, false, false)
        }
        fn run_image_profiles_mode(
            fx: &Fixture,
            mut state: SessionState,
            evidence: &SkillEvidence,
            source: Arc<ScriptedGenerationSource>,
            fallback: bool,
            ancestor: bool,
            ancillary: bool,
        ) -> (ExitReason, bool, SessionState) {
            let inherited = ancestor.then(|| {
                use ego_core::session::{
                    ReplayContext, ReplaySource, ReplaySourceError, SessionBlobSource,
                    SessionLineage,
                };
                use ego_core::store::blob::{BlobError, BlobRef, BlobStore};
                use ego_core::store::session_store::SessionEntry;

                // The production replay port owns event and session-qualified
                // blob reads; no already-hydrated Conversation is injected.
                struct ImageAncestor<'a> {
                    session: SessionId,
                    entries: Vec<SessionEntry>,
                    blobs: &'a common::MemoryBlobStore,
                    reads: AtomicUsize,
                }
                impl ReplaySource for ImageAncestor<'_> {
                    fn lineage(
                        &self,
                        session: &SessionId,
                    ) -> Result<Option<SessionLineage>, ReplaySourceError> {
                        assert_eq!(*session, self.session);
                        Ok(None)
                    }
                    fn entries(
                        &self,
                        session: &SessionId,
                    ) -> Result<Option<Vec<SessionEntry>>, ReplaySourceError> {
                        assert_eq!(*session, self.session);
                        Ok(Some(self.entries.clone()))
                    }
                }
                impl SessionBlobSource for ImageAncestor<'_> {
                    fn read(
                        &self,
                        session: &SessionId,
                        reference: &BlobRef,
                    ) -> Result<Vec<u8>, BlobError> {
                        assert_eq!(*session, self.session);
                        self.reads.fetch_add(1, Ordering::SeqCst);
                        self.blobs.read(reference)
                    }
                }
                let events = image_seed_events(evidence, false);
                let cutoff = events.last().unwrap().env.seq;
                let source = ImageAncestor {
                    session: SessionId::new(),
                    // Exercise durable event decoding before the lineage replay.
                    entries: events
                        .into_iter()
                        .map(|event| {
                            let encoded = serde_json::to_vec(&event).unwrap();
                            SessionEntry::Event(serde_json::from_slice(&encoded).unwrap())
                        })
                        .collect(),
                    blobs: &evidence.blobs,
                    reads: AtomicUsize::new(0),
                };
                let replayed = ReplayContext::new(&source, &source)
                    .replay_lineage(SessionLineage::Fork {
                        source: source.session,
                        at_seq: cutoff,
                        neutral: false,
                    })
                    .unwrap();
                assert_eq!(source.reads.load(Ordering::SeqCst), 1);
                assert_eq!(replayed.session_pins(), &[source.session]);
                let images: Vec<_> = replayed
                    .conversation()
                    .messages()
                    .iter()
                    .flat_map(|message| &message.content)
                    .filter_map(|block| match block {
                        ContentBlock::Image { image } => Some(image.bytes()),
                        _ => None,
                    })
                    .collect();
                assert_eq!(
                    images,
                    vec![PNG_1X1],
                    "ancestor replay must really hydrate the original bytes"
                );
                state = SessionState::default();
                replayed
            });
            let gate = fx.gate.borrow_mut();
            let tools = Tools::new(
                &fx.registry,
                ToolEffectPorts::new(
                    &fx.fs,
                    fx.process.as_ref(),
                    evidence,
                    Arc::new(NoResolver),
                    Arc::new(NoHop),
                    Arc::new(NoDuplex),
                ),
                CanonPath::new("/ws"),
            );
            let mut turn = TurnLoop::open(
                session(state, &fx.store, &fx.clock, &fx.sink, CancelToken::new()),
                GenerationRuntime {
                    policy_source: fx.policy_source.clone(),
                    source,
                    gate: gate.clone(),
                    config: TurnConfig {
                        cache: CacheRetention::None,
                        system: None,
                        identity: None,
                        token_ceiling: None,
                        retry: 0,
                        fallbacks: if fallback {
                            vec![ModelRef("fixture/fallback".into())]
                        } else {
                            vec![]
                        },
                    },
                    admission: Arc::new(EvidenceAdmissionService::new()),
                    invocation: RunInvocationId::new(),
                    retry_pause: Arc::new(NoRetryPause),
                },
                tools,
            );
            if let Some(history) = inherited {
                turn = turn.with_replayed_context(&history);
            }
            let outcome = block_on(turn.run("continue from the tool result")).unwrap();
            if ancillary {
                let recap = block_on(turn.recap(&CancelToken::new()));
                assert!(recap.is_ok(), "text-only recap must project tool images");
                let compacted = block_on(turn.prepare_compaction(None, vec![]));
                assert!(
                    compacted.is_ok(),
                    "text-only compaction must project tool images: {compacted:?}"
                );
            }
            (outcome.exit_reason, outcome.ok, turn.into_state().unwrap())
        }
        fn request_images(request: &GenRequest) -> Vec<&[u8]> {
            request
                .messages
                .messages()
                .iter()
                .flat_map(|m| &m.content)
                .filter_map(|b| match b {
                    ContentBlock::Image { image } => Some(image.bytes()),
                    _ => None,
                })
                .collect()
        }
        #[test]
        fn text_only_turn_continues_with_tool_text_receipt_and_durable_original() {
            // Catches preflight refusing an otherwise valid completed tool result.
            let fx = Fixture::new(vec![]);
            let evidence = SkillEvidence::new();
            let seed = image_seed(&evidence, false);
            let original = seed.blob_references();
            let trace = GenerationTrace::default();
            let source = Arc::new(ScriptedGenerationSource::new([Ok(image_profile(
                "fixture/text",
                false,
                vec![AiEvent::Stop(StopReason::Stop)],
                &trace,
            ))]));
            let (_, ok, state) = run_image_profiles(&fx, seed, &evidence, source, false);
            assert!(ok);
            let requests = trace.requests.lock().unwrap();
            assert_eq!(requests.len(), 1);
            assert!(request_images(&requests[0]).is_empty());
            let blocks: Vec<_> = requests[0]
                .messages
                .messages()
                .iter()
                .flat_map(|m| &m.content)
                .collect();
            assert!(
                blocks
                    .iter()
                    .any(|b| matches!(b,ContentBlock::ToolResult{call_id,output,..}
                if call_id=="image-read" && output=="sibling coordinates x=11,y=12"))
            );
            assert!(blocks.iter().any(|b| matches!(b,ContentBlock::Text{text}
                if text.starts_with("[Tool image unavailable:"))));
            assert!(original.iter().all(|r| state.blob_references().contains(r)));
        }
        #[test]
        fn fallback_in_both_directions_reprojects_original_tool_images() {
            // Catches a text candidate permanently stripping canonical images,
            // or a vision candidate leaking them into a text-only fallback.
            for first_vision in [false, true] {
                let fx = Fixture::new(vec![]);
                let evidence = SkillEvidence::new();
                let seed = image_seed(&evidence, false);
                let trace = GenerationTrace::default();
                let source = Arc::new(ScriptedGenerationSource::new([
                    Ok(image_profile(
                        "fixture/primary",
                        first_vision,
                        vec![
                            AiEvent::Error {
                                message: "refused before write".into(),
                                kind: ErrorKind::Transient,
                            },
                            AiEvent::DeliveryObserved(DeliveryCertainty::DefinitelyUnsent),
                            AiEvent::Stop(StopReason::Error),
                        ],
                        &trace,
                    )),
                    Ok(image_profile(
                        "fixture/fallback",
                        !first_vision,
                        vec![AiEvent::Stop(StopReason::Stop)],
                        &trace,
                    )),
                ]));
                let (_, ok, _) = run_image_profiles(&fx, seed, &evidence, source, true);
                assert!(ok);
                let requests = trace.requests.lock().unwrap();
                assert_eq!(requests.len(), 2);
                for (request, vision) in requests.iter().zip([first_vision, !first_vision]) {
                    assert_eq!(
                        request_images(request),
                        if vision { vec![PNG_1X1] } else { vec![] }
                    );
                }
            }
        }
