        #[test]
        fn recap_and_compaction_project_tool_images_before_prefix_and_cache_accounting() {
            // Catches ancillary text-only models refusing image-bearing history,
            // and comparing a projected prefix with an unprojected main request.
            for main_vision in [false, true] {
                let fx = Fixture::new(vec![]);
                let evidence = SkillEvidence::new();
                let seed = image_seed(&evidence, false);
                let trace = GenerationTrace::default();
                // Compaction parses a checkpoint, not arbitrary recap prose.
                // A valid response keeps this test on image projection rather
                // than consuming the separate corrective-generation path.
                let checkpoint = concat!(
                    "# Objective\nContinue from the tool observation.\n",
                    "# Binding constraints and preferences\nNone.\n",
                    "# Completed work and evidence\nRead the image and coordinates.\n",
                    "# Work in progress\nNone.\n",
                    "# Decisions and rationale\nPreserve the tool evidence.\n",
                    "# Blockers and uncertainty\nNone.\n",
                    "# Ordered next steps\nContinue the task.\n",
                    "# Critical references\nThe correlated read result.\n",
                );
                ego_core::compact::Checkpoint::parse(checkpoint)
                    .expect("the scripted compaction response is a valid checkpoint");
                let summary = || {
                    vec![
                        AiEvent::TextDelta {
                            text: checkpoint.into(),
                        },
                        AiEvent::Stop(StopReason::Stop),
                    ]
                };
                let summary_profile = || {
                    let mut profile = image_profile("fixture/text", false, summary(), &trace);
                    // Exercise the in-window cache path, not transcript fitting,
                    // which deliberately clears the cache on oversized input.
                    profile.capabilities.max_context_tokens = Some(128_000);
                    profile
                };
                let source = Arc::new(ScriptedGenerationSource::new([
                    Ok(image_profile(
                        "fixture/main",
                        main_vision,
                        vec![AiEvent::Stop(StopReason::Stop)],
                        &trace,
                    )),
                    Ok(summary_profile()),
                    Ok(summary_profile()),
                    Ok(image_profile("fixture/main", false, vec![], &trace)),
                ]));
                let (_, ok, _) =
                    run_image_profiles_mode(&fx, seed, &evidence, source, false, false, true);
                assert!(ok);
                let requests = trace.requests.lock().unwrap();
                assert_eq!(requests.len(), 3);
                for request in &requests[1..] {
                    assert!(request_images(request).is_empty());
                    let cache = request.cache.as_ref().unwrap();
                    assert!(cache.stable_messages < request.messages.messages().len());
                    if main_vision {
                        assert_eq!(cache.stable_messages, request.messages.messages().len() - 1);
                    }
                }
                if !main_vision {
                    let blocks = |request: &GenRequest| {
                        request
                            .messages
                            .messages()
                            .iter()
                            .flat_map(|m| m.content.iter().map(move |b| (m.role, b.clone())))
                            .collect::<Vec<_>>()
                    };
                    assert!(blocks(&requests[1]).starts_with(&blocks(&requests[0])));
                    assert_eq!(requests[1].cache, requests[0].cache);
                }
            }
        }

        fn run_scripted(
            fx: &Fixture,
            state: SessionState,
            prompt: &str,
            source: Arc<ScriptedGenerationSource>,
            config: TurnConfig,
        ) -> (ExitReason, bool, SessionState) {
            run_scripted_mode(fx, state, prompt, source, config, None)
        }

        fn run_scripted_mode(
            fx: &Fixture,
            state: SessionState,
            prompt: &str,
            source: Arc<ScriptedGenerationSource>,
            config: TurnConfig,
            automatic: Option<ego_core::compact::ContextPercent>,
        ) -> (ExitReason, bool, SessionState) {
            let gate = fx.gate.borrow_mut();
            let tools = Tools::new(
                &fx.registry,
                ToolEffectPorts::new(
                    &fx.fs,
                    fx.process.as_ref(),
                    &fx.evidence,
                    Arc::new(NoResolver),
                    Arc::new(NoHop),
                    Arc::new(NoDuplex),
                ),
                CanonPath::new("/ws"),
            );
            let mut turn = TurnLoop::open(
                session(state, &fx.store, &fx.clock, &fx.sink, CancelToken::new()),
                GenerationRuntime {
                    policy_source: fx.policy_source.clone(),
                    source,
                    gate: gate.clone(),
                    config,
                    admission: Arc::new(EvidenceAdmissionService::new()),
                    invocation: RunInvocationId::new(),
                    retry_pause: Arc::new(NoRetryPause),
                },
                tools,
            );
            if let Some(threshold) = automatic {
                turn = turn
                    .with_automatic_compaction()
                    .with_compaction_threshold(threshold);
            }
            let outcome = block_on(turn.run(prompt)).expect("the store accepted every append");
            (
                outcome.exit_reason,
                outcome.ok,
                turn.into_state().expect("unique turn journal state"),
            )
        }

