        // Catches: narration recovery escapes its seat, cap, cancellation or unsafe-content boundaries.
        #[test]
        fn narration_retry_preserves_seat_allowance_and_output_safety() {
            let horizon = Some(ego_core::turn::PROVIDER_RECOVERY_HORIZON);
            for (name, interactive, retry, recovery, cancel_wait, opaque, extra, expected) in [
                ("finite cap", true, 6, None, false, true, None, 2),
                ("text only", true, 6, None, false, false, None, 2),
                ("horizon cap", true, 6, horizon, false, true, None, 2),
                ("zero", true, 0, None, false, true, None, 1),
                ("headless", false, 6, None, false, true, None, 1),
                ("cancel wait", true, 6, None, true, true, None, 1),
                (
                    "visible reasoning",
                    true,
                    6,
                    None,
                    false,
                    true,
                    Some(AiEvent::ReasoningDelta {
                        text: "thinking".into(),
                    }),
                    1,
                ),
                (
                    "unrun tool mixed with text",
                    true,
                    6,
                    None,
                    false,
                    true,
                    Some(AiEvent::ToolCall {
                        call_id: "not-run".into(),
                        name: "write".into(),
                        args: "{}".into(),
                    }),
                    1,
                ),
                (
                    "hidden provider effects",
                    true,
                    6,
                    None,
                    false,
                    true,
                    Some(AiEvent::ProviderContent {
                        state: ReasoningState {
                            connection: None,
                            blob: "unknown effect".into(),
                            dialect: "fixture".into(),
                        },
                        visible: false,
                    }),
                    1,
                ),
                (
                    "visible provider effects",
                    true,
                    6,
                    None,
                    false,
                    true,
                    Some(AiEvent::ProviderContent {
                        state: ReasoningState {
                            connection: None,
                            blob: "unknown effect".into(),
                            dialect: "fixture".into(),
                        },
                        visible: true,
                    }),
                    1,
                ),
            ] {
                let trace = GenerationTrace::default();
                let mut script = recorded_710_narration();
                if !opaque {
                    script.retain(|event| !matches!(event, AiEvent::ReasoningState(_)));
                }
                if let Some(extra) = extra {
                    script.insert(0, extra);
                }
                let source = Arc::new(
                    ScriptedGenerationSource::new((0..3).map(|_| {
                        Ok(profile(
                            "ollama/primary-model",
                            false,
                            script.clone(),
                            &trace,
                            Some(1_024),
                        ))
                    }))
                    .with_trace(trace.clone()),
                );
                let fx = Fixture::new(vec![]);
                let cancel = CancelToken::new();
                let pause = Arc::new(RecordedPause {
                    cancel_on_wait: cancel_wait.then(|| cancel.clone()),
                    ..Default::default()
                });
                let (_ingress, mut control) = ego_core::turn::interactive_control();
                let outcome = run_retrying_controlled(
                    &fx,
                    source,
                    retry,
                    pause.clone(),
                    cancel,
                    interactive.then_some(&mut control),
                    recovery,
                );
                assert_eq!(trace.requests.lock().unwrap().len(), expected, "{name}");
                assert_eq!(
                    pause.delays.lock().unwrap().len(),
                    usize::from(expected == 2 || cancel_wait),
                    "{name}"
                );
                assert_eq!(
                    outcome.exit_reason,
                    if cancel_wait {
                        ExitReason::Cancelled(ego_core::event::domain::CancelCause::Host)
                    } else {
                        ExitReason::Provider
                    },
                    "{name}"
                );
                let events = fx.store.events();
                let markers = events
                    .iter()
                    .filter(|event| {
                        // Story 842: the marker chunk is live only; the
                        // assembled replacement carries it durably.
                        matches!(&event.kind,
                    EventKind::AssistantMessage { text } if text.ends_with("\n\n[interrupted]"))
                    })
                    .count();
                assert_eq!(
                    markers,
                    usize::from(expected == 2),
                    "{name}: only retried narration gets a marker"
                );
                assert!(
                    events.iter().all(|event| !matches!(
                        &event.kind,
                        EventKind::ToolCallCompleted { ok: true, .. }
                    )),
                    "{name}: failed tools never run"
                );
            }
        }

        // Recorded events, not invented provider fixtures: story 615 retained the live JSONL slices.
        fn recorded_615_attempts() -> Vec<(&'static str, Vec<AiEvent>)> {
            [
                (
                    "exec",
                    include_str!("../../../ego-cli/tests/fixtures/615-unrun-exec.jsonl"),
                ),
                (
                    "swift-live-617",
                    include_str!("../../../ego-cli/tests/fixtures/617-unrun-swift.jsonl"),
                ),
                (
                    "write",
                    include_str!("../../../ego-cli/tests/fixtures/615-unrun-write.jsonl"),
                ),
                (
                    "exec-without-reasoning",
                    include_str!(
                        "../../../ego-cli/tests/fixtures/615-unrun-exec-without-reasoning.jsonl"
                    ),
                ),
            ]
            .into_iter()
            .map(|(name, fixture)| {
                let mut events = Vec::new();
                for line in fixture.lines() {
                    let record: serde_json::Value = serde_json::from_str(line).unwrap();
                    let kind: EventKind =
                        serde_json::from_value(record["payload"]["event"]["kind"].clone()).unwrap();
                    match kind {
                        EventKind::ReasoningState { state } => {
                            events.push(AiEvent::ReasoningState(state))
                        }
                        EventKind::ToolCallStarted {
                            name,
                            args,
                            call_id,
                        } => events.push(AiEvent::ToolCall {
                            name,
                            args,
                            call_id: call_id.expect("recorded provider call ID"),
                        }),
                        EventKind::Error { message, kind } => {
                            events.push(AiEvent::Error { message, kind })
                        }
                        EventKind::AttemptSettled { outcome, .. } => {
                            assert_eq!(outcome.stop(), StopReason::Error);
                            events.push(AiEvent::DeliveryObserved(outcome.delivery()));
                            events.push(AiEvent::Stop(outcome.stop()));
                        }
                        _ => {}
                    }
                }
                (name, events)
            })
            .collect()
        }

        // Catches: opaque reasoning and parsed-but-unrun tools suppress safe recovery or remain open.
        #[test]
        fn recorded_615_unrun_attempts_retry_once_and_close_tools() {
            let mut failed = Vec::new();
            for (name, events) in recorded_615_attempts() {
                let trace = GenerationTrace::default();
                let source = Arc::new(
                    ScriptedGenerationSource::new([
                        Ok(profile(
                            "ollama/primary-model",
                            false,
                            events,
                            &trace,
                            Some(1_024),
                        )),
                        Ok(profile(
                            "ollama/primary-model",
                            false,
                            vec![
                                AiEvent::TextDelta {
                                    text: "Recovered.".into(),
                                },
                                AiEvent::Stop(StopReason::Stop),
                            ],
                            &trace,
                            Some(1_024),
                        )),
                    ])
                    .with_trace(trace.clone()),
                );
                let fx = Fixture::new(vec![]);
                let pause = Arc::new(RecordedPause::default());
                let outcome = run_retrying(&fx, source, 6, pause.clone(), CancelToken::new());
                let events = fx.store.events();
                let starts: Vec<_> = events
                    .iter()
                    .enumerate()
                    .filter(|(_, event)| matches!(event.kind, EventKind::GenerationStarted { .. }))
                    .map(|(i, _)| i)
                    .collect();
                let completions: Vec<_> = events
                    .iter()
                    .enumerate()
                    .filter_map(|(i, event)| match &event.kind {
                        EventKind::ToolCallCompleted { ok, result } => {
                            Some((i, *ok, result.model_text()))
                        }
                        _ => None,
                    })
                    .collect();
                let settlements = events
                    .iter()
                    .filter(|event| matches!(event.kind, EventKind::AttemptSettled { .. }))
                    .count();
                let charges = events
                    .iter()
                    .filter(|event| matches!(event.kind, EventKind::UsageUpdated { .. }))
                    .count();
                if !outcome.ok || trace.requests.lock().unwrap().len() != 2 {
                    failed.push(format!(
                        "{name}: {:?}, {} requests",
                        outcome.exit_reason,
                        trace.requests.lock().unwrap().len()
                    ));
                    continue;
                }
                assert_eq!(settlements, 2, "{name}: every attempt settles");
                assert_eq!(charges, 2, "{name}: every attempt keeps its accounting");
                assert_eq!(
                    completions.len(),
                    1,
                    "{name}: no partial tool executes or closes twice"
                );
                assert!(!completions[0].1);
                assert_eq!(completions[0].2, "interrupted: not run");
                assert!(
                    completions[0].0 < starts[1],
                    "{name}: pending tools must close before retry"
                );
                assert_eq!(pause.delays.lock().unwrap().len(), 1);
                assert!(events.iter().any(|event| matches!(&event.kind, EventKind::AssistantMessage { text } if text == "Recovered.")));
            }
            assert!(failed.is_empty(), "{}", failed.join("\n"));
        }

        // Catches: the new recovery bypasses zero retry, cancellation, or the one-retry cap.
        #[test]
        fn unrun_retry_respects_one_retry_zero_allowance_and_cancellation() {
            for opaque_only in [false, true] {
                for (retry, recovery, cancel_wait, expected) in [
                    (0, None, false, 1),
                    (6, None, false, 2),
                    (6, Some(ego_core::turn::PROVIDER_RECOVERY_HORIZON), false, 2),
                    (6, None, true, 1),
                ] {
                    let trace = GenerationTrace::default();
                    let mut recorded = recorded_615_attempts().remove(0).1;
                    if opaque_only {
                        recorded.retain(|event| !matches!(event, AiEvent::ToolCall { .. }));
                    }
                    let source = Arc::new(
                        ScriptedGenerationSource::new((0..3).map(|index| {
                            let mut events = recorded.clone();
                            for event in &mut events {
                                if let AiEvent::ToolCall { call_id, .. } = event {
                                    call_id.push_str(&index.to_string());
                                }
                            }
                            Ok(profile(
                                "ollama/primary-model",
                                false,
                                events,
                                &trace,
                                Some(1_024),
                            ))
                        }))
                        .with_trace(trace.clone()),
                    );
                    let fx = Fixture::new(vec![]);
                    let cancel = CancelToken::new();
                    let pause = Arc::new(RecordedPause {
                        cancel_on_wait: cancel_wait.then(|| cancel.clone()),
                        ..Default::default()
                    });
                    let outcome =
                        run_retrying_controlled(&fx, source, retry, pause, cancel, None, recovery);
                    assert_eq!(
                        trace.requests.lock().unwrap().len(),
                        expected,
                        "opaque={opaque_only}, retry={retry}, recovery={recovery:?}, cancel={cancel_wait}"
                    );
                    assert_eq!(
                        outcome.exit_reason,
                        if cancel_wait {
                            ExitReason::Cancelled(ego_core::event::domain::CancelCause::Host)
                        } else {
                            ExitReason::Provider
                        }
                    );
                    if !cancel_wait {
                        assert!(
                            outcome.provider_failure.unwrap().effect_known,
                            "no output or tool effect is uncertain"
                        );
                    }
                    let events = fx.store.events();
                    let started = events
                        .iter()
                        .filter(|event| matches!(event.kind, EventKind::ToolCallStarted { .. }))
                        .count();
                    let completed = events
                        .iter()
                        .filter(|event| matches!(event.kind, EventKind::ToolCallCompleted { .. }))
                        .count();
                    assert_eq!(
                        started, completed,
                        "even a cancelled retry must close pending tools"
                    );
                }
            }
        }

        // Catches: retry executes a failed attempt's partial tool, or repeats a recovered effect.
        #[test]
        fn recovered_unrun_attempt_dispatches_only_the_successful_tool_once() {
            let trace = GenerationTrace::default();
            let mut scripts = vec![recorded_615_attempts().remove(0).1];
            scripts.extend(writing("/ws/recovered.txt", "one effect"));
            let source = Arc::new(
                ScriptedGenerationSource::new(scripts.into_iter().map(|events| {
                    Ok(profile_with_carryover(
                        "ollama/primary-model",
                        events,
                        &trace,
                        ReasoningCarryover::SameProviderOnly,
                        Some("openai-codex-responses"),
                    ))
                }))
                .with_trace(trace.clone()),
            );
            let fx = Fixture::new(vec![])
                .with_write_tool()
                .with_rules(&["write(**)"], &[]);
            let outcome = run_retrying(
                &fx,
                source,
                6,
                Arc::new(RecordedPause::default()),
                CancelToken::new(),
            );
            assert!(outcome.ok);
            assert_eq!(
                fx.fs.read(&CanonPath::new("/ws/recovered.txt")).unwrap(),
                b"one effect"
            );
            let events = fx.store.events();
            let results: Vec<_> = events
                .iter()
                .filter_map(|event| match &event.kind {
                    EventKind::ToolCallCompleted { ok, result } => Some((*ok, result.model_text())),
                    _ => None,
                })
                .collect();
            assert_eq!(results.len(), 2);
            assert_eq!(results[0], (false, "interrupted: not run".into()));
            assert!(results[1].0);
            assert_eq!(trace.requests.lock().unwrap().len(), 3);
        }

        struct RecoveryBoundaryClock {
            now: Mutex<std::time::Instant>,
        }

        impl ego_core::turn::RetryPause for RecoveryBoundaryClock {
            fn now(&self) -> std::time::Instant {
                *self.now.lock().unwrap()
            }
            fn pause(&self, delay: std::time::Duration) -> BoxFuture<'static, ()> {
                *self.now.lock().unwrap() += delay;
                Box::pin(futures::future::ready(()))
            }
        }

        struct ExpiringResolution {
            inner: ScriptedGenerationSource,
            clock: Arc<RecoveryBoundaryClock>,
            calls: std::sync::atomic::AtomicUsize,
        }

        impl GenerationModelSource for ExpiringResolution {
            fn resolve<'a>(
                &'a self,
                request: GenerationModelRequest,
            ) -> BoxFuture<'a, Result<GenerationProfile, GenerationModelError>> {
                if self.calls.fetch_add(1, std::sync::atomic::Ordering::SeqCst) == 1 {
                    *self.clock.now.lock().unwrap() += std::time::Duration::from_secs(2);
                }
                self.inner.resolve(request)
            }
        }

        fn run_recovery_boundary(
            fx: &Fixture,
            source: Arc<dyn GenerationModelSource>,
            pause: Arc<RecoveryBoundaryClock>,
            fallbacks: Vec<ModelRef>,
        ) -> ego_core::turn::TurnOutcome {
            let gate = fx.gate.borrow_mut();
            let tools = Tools::new(
                &fx.registry,
                ToolEffectPorts::new(
                    &fx.fs,
                    fx.process.as_ref(),
                    &fx.evidence,
                    Arc::new(NoResolver),
                    Arc::new(NoHop),
                    Arc::new(NoDuplex),
                ),
                CanonPath::new("/ws"),
            );
            let mut turn = TurnLoop::open(
                session(
                    SessionState::default(),
                    &fx.store,
                    &fx.clock,
                    &fx.sink,
                    CancelToken::new(),
                ),
                GenerationRuntime {
                    policy_source: fx.policy_source.clone(),
                    source,
                    gate: gate.clone(),
                    config: TurnConfig {
                        cache: ego_core::generator::capabilities::CacheRetention::Short,
                        system: None,
                        identity: None,
                        token_ceiling: None,
                        retry: 0,
                        fallbacks,
                    },
                    admission: Arc::new(EvidenceAdmissionService::new()),
                    invocation: RunInvocationId::new(),
                    retry_pause: pause,
                },
                tools,
            )
            .with_provider_recovery(Some(std::time::Duration::from_secs(2)));
            block_on(turn.run("recover without starting a late request")).unwrap()
        }

        /// Catches: model resolution crosses the horizon but starts a paid request anyway.
        #[test]
        fn recovery_horizon_prevents_request_after_slow_model_resolution() {
            let fx = Fixture::new(vec![]);
            let trace = GenerationTrace::default();
            let clock = Arc::new(RecoveryBoundaryClock {
                now: Mutex::new(std::time::Instant::now()),
            });
            let source = Arc::new(ExpiringResolution {
                inner: ScriptedGenerationSource::new([
                    Ok(profile(
                        "openai/main",
                        false,
                        overloaded(None),
                        &trace,
                        Some(1_024),
                    )),
                    Ok(profile(
                        "openai/main",
                        false,
                        vec![AiEvent::Stop(StopReason::Stop)],
                        &trace,
                        Some(1_024),
                    )),
                ]),
                clock: clock.clone(),
                calls: std::sync::atomic::AtomicUsize::new(0),
            });
            let _ = run_recovery_boundary(&fx, source, clock, vec![]);
            assert_eq!(
                trace.requests.lock().unwrap().len(),
                1,
                "an expired recovery horizon must prevent dispatch after model resolution"
            );
        }

