        fn capacity_flags(fx: &Fixture) -> Vec<bool> {
            fx.sink
                .events()
                .into_iter()
                .filter_map(|event| match event {
                    PublicEvent::ProviderRetry { capacity, .. } => Some(capacity),
                    _ => None,
                })
                .collect()
        }

