    #[test]
    fn skill_review_isolated_and_high_risk_requires_operator_approval() {
        use ego_core::question::{
            Elicitor, ElicitorError, QuestionAnswer, QuestionOutcome, QuestionRequest,
        };
        struct Confirm(AtomicBool);
        impl Elicitor for Confirm {
            fn elicit<'a>(
                &'a self,
                _: ItemId,
                request: QuestionRequest,
            ) -> BoxFuture<'a, Result<QuestionOutcome, ElicitorError>> {
                assert!(
                    request.prompt.contains("unauthorized transfer")
                        || request.prompt.contains("valid verdict")
                );
                assert!(request.prompt.contains("Existing permissions still apply"));
                Box::pin(std::future::ready(Ok(
                    if self.0.swap(false, Ordering::SeqCst) {
                        QuestionOutcome::Answered(QuestionAnswer::single("allow_once"))
                    } else {
                        QuestionOutcome::Declined
                    },
                )))
            }
        }
        // Catches: approving from model output, leaking the argument/history into the review,
        // executing a reviewer tool request, or reaching the main model before consent.
        for (case, reviewer, allow, admitted) in [
            ("blocked", "\"exfiltration\"", false, false),
            ("approved", "\"exfiltration\"", true, true),
            ("invalid", "{\"allow_once\":true}", false, false),
            ("tool attempt", "\"clear\"", false, false),
            ("clear", "\"clear\"", false, true),
        ] {
            let descriptor = forked_descriptor(true);
            let body = format!("Fixture {case}: command text is only evidence");
            let catalogue = Arc::new(
                ego_core::skill::SkillCatalogue::new(vec![
                    ego_core::skill::SkillSpec::new(descriptor.clone(), body.into_bytes()).unwrap(),
                ])
                .unwrap(),
            );
            let mut review_events = vec![AiEvent::TextDelta {
                text: reviewer.into(),
            }];
            if case == "tool attempt" {
                review_events.push(AiEvent::ToolCall {
                    call_id: "reviewer-tool-attempt".into(),
                    name: "skill".into(),
                    args: json!({"kind": "invoke", "name": "forked"}).to_string(),
                });
            }
            review_events.push(AiEvent::Stop(StopReason::Stop));
            let fx = Fixture::new(vec![review_events, vec![AiEvent::Stop(StopReason::Stop)]]);
            let evidence = SkillEvidence::new();
            let mut gate = fx.gate.borrow_mut();
            let tools = Tools::from_registry(
                &[RegisteredTool::skill(catalogue)],
                ToolEffectPorts::new(
                    &fx.fs,
                    fx.process.as_ref(),
                    &evidence,
                    Arc::new(NoResolver),
                    Arc::new(NoHop),
                    Arc::new(NoDuplex),
                ),
                CanonPath::new("/ws"),
            );
            let mut turn = TurnLoop::open(
                session(
                    SessionState::default(),
                    &fx.store,
                    &fx.clock,
                    &fx.sink,
                    CancelToken::new(),
                ),
                model_for(&fx, &fx.generator, &mut gate),
                tools,
            )
            .with_skill_review(true)
            .with_elicitor(Arc::new(Confirm(AtomicBool::new(allow))))
            .with_skill_invocation_port(Arc::new(RecordingSkillInvocationPort::default()));
            let operation =
                ego_core::skill::AdmittedSkillOperation::invoke(&descriptor, "PRIVATE ARGUMENT");
            let outcome = block_on(turn.run_admitted_skill(operation)).unwrap();
            assert_eq!(outcome.ok, admitted, "{case}");
            let calls = fx.generator.calls();
            assert_eq!(calls.len(), 1 + usize::from(admitted));
            let review = &calls[0];
            assert!(review.tools.is_empty());
            assert!(review.web_search.is_none() && review.cache.is_none());
            assert_eq!(review.messages.messages().len(), 2);
            let input = serde_json::to_string(&review.messages).unwrap();
            assert!(input.contains("untrusted_skill_evidence"));
            assert!(input.contains("command text is only evidence"));
            assert!(!input.contains("PRIVATE ARGUMENT"));
            assert_eq!(
                fx.store
                    .events()
                    .iter()
                    .any(|event| matches!(event.kind, EventKind::SkillInstructionAdmitted { .. })),
                admitted
            );
            if allow {
                let operation = ego_core::skill::AdmittedSkillOperation::invoke(
                    &descriptor,
                    "PRIVATE ARGUMENT",
                );
                let retry = block_on(turn.run_admitted_skill(operation)).unwrap();
                assert!(
                    !retry.ok,
                    "the previous approval must not authorize another use"
                );
                assert_eq!(
                    fx.generator.calls().len(),
                    2,
                    "reuse the verdict, not the approval"
                );
            }
        }
    }

    #[test]
    fn typed_user_skill_turn_uses_admitted_instruction_not_prompt_or_tool_call() {
        let location =
            ego_core::event::skill::SkillSourceLocation::parse("skills/explain/SKILL.md")
                .expect("skill source location");
        let source_digest = ego_core::event::skill::SkillContentDigest::parse(
            "0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef",
        )
        .expect("skill source digest");
        let descriptor = ego_core::event::skill::SkillDescriptorEvidence {
            id: ego_core::event::skill::SkillId::derive(
                ego_core::event::skill::SkillSourceAuthority::User,
                &location,
                "explain",
                &source_digest,
            ),
            name: "explain".to_owned(),
            description: "Explain a request".to_owned(),
            trigger: None,
            argument_hint: None,
            source: ego_core::event::skill::SkillSourceAuthority::User,
            location,
            source_digest,
            user_invocable: true,
            model_invocable: false,
        };
        let catalogue = Arc::new(
            ego_core::skill::SkillCatalogue::new(vec![
                ego_core::skill::SkillSpec::new(
                    descriptor.clone(),
                    b"Explain this request: $ARGUMENTS".to_vec(),
                )
                .expect("admitted skill")
                .with_model(ModelRef("skill-model".to_owned()), "high"),
            ])
            .expect("admitted catalogue"),
        );
        let arguments = "preserve these raw arguments: {x: 1}";
        let operation = ego_core::skill::AdmittedSkillOperation::invoke(&descriptor, arguments);
        let fx = Fixture::new(vec![
            vec![
                AiEvent::TextDelta {
                    text: "done".to_owned(),
                },
                AiEvent::Stop(StopReason::Stop),
            ],
            vec![
                AiEvent::TextDelta {
                    text: "ordinary done".to_owned(),
                },
                AiEvent::Stop(StopReason::Stop),
            ],
        ]);
        let skill_evidence = SkillEvidence::new();
        let mut gate = fx.gate.borrow_mut();
        let tools = Tools::from_registry(
            &[RegisteredTool::skill(Arc::clone(&catalogue))],
            ToolEffectPorts::new(
                &fx.fs,
                fx.process.as_ref(),
                &skill_evidence,
                Arc::new(NoResolver),
                Arc::new(NoHop),
                Arc::new(NoDuplex),
            ),
            CanonPath::new("/ws"),
        );
        let mut turn = TurnLoop::open(
            session(
                SessionState::default(),
                &fx.store,
                &fx.clock,
                &fx.sink,
                CancelToken::new(),
            ),
            model_for(&fx, &fx.generator, &mut gate),
            tools,
        )
        .with_skill_invocation_port(Arc::new(RecordingSkillInvocationPort::default()));

        let outcome =
            block_on(turn.run_admitted_skill(operation)).expect("the store accepted every append");
        let typed_turn = outcome.turn;
        assert_eq!(outcome.exit_reason, ExitReason::Completed);
        assert!(outcome.ok);

        let calls = fx.generator.calls();
        assert_eq!(calls.len(), 1, "a typed skill invokes one generation");
        let request = &calls[0];
        assert_eq!(request.model, "skill-model");
        assert_eq!(
            request
                .tools
                .iter()
                .filter(|tool| tool.name == "skill")
                .count(),
            1,
            "the mixed registry exposes the skill tool to the generation"
        );
        let instruction = request
            .messages
            .messages()
            .iter()
            .filter(|message| message.role == Role::User)
            .flat_map(|message| message.content.iter())
            .find_map(|block| match block {
                ContentBlock::Text { text } if text.contains("Admitted skill instruction (") => {
                    Some(text)
                }
                _ => None,
            })
            .expect("the request carries the admitted skill in the ego-owned context tail");
        assert!(
            instruction.contains("\nExplain this request: preserve these raw arguments: {x: 1}"),
            "the request contains the rendered skill body: {instruction}"
        );
        assert!(
            instruction.contains(arguments),
            "the exact raw arguments survive rendering"
        );

        let events = fx.store.events();
        let catalogue_at = events
            .iter()
            .position(|event| {
                event.env.turn == typed_turn
                    && matches!(&event.kind, EventKind::SkillCatalogueAdmitted { .. })
            })
            .expect("catalogue admission is durable");
        let instruction_at = events
            .iter()
            .position(|event| {
                event.env.turn == typed_turn
                    && matches!(&event.kind, EventKind::SkillInstructionAdmitted { .. })
            })
            .expect("instruction admission is durable");
        let generation_at = events
            .iter()
            .position(|event| {
                event.env.turn == typed_turn
                    && matches!(&event.kind, EventKind::GenerationStarted { .. })
            })
            .expect("generation start is durable");
        assert!(catalogue_at < instruction_at && instruction_at < generation_at);
        assert!(!events.iter().any(|event| {
            event.env.turn == typed_turn && matches!(&event.kind, EventKind::UserPrompt { .. })
        }));
        assert!(!events.iter().any(|event| matches!(
            &event.kind,
            EventKind::ToolCallStarted { .. } | EventKind::ToolCallCompleted { .. }
        ) && event.env.turn == typed_turn));

        let ordinary =
            block_on(turn.run("ordinary")).expect("the store accepted every ordinary append");
        assert_eq!(ordinary.exit_reason, ExitReason::Completed);
        let calls = fx.generator.calls();
        assert_eq!(
            calls.len(),
            2,
            "the ordinary turn invokes one more generation"
        );
        assert_eq!(
            calls[1].model, "test-model",
            "the skill model pin is cleared"
        );
        assert!(calls[1].messages.messages().iter().any(|message| {
            message.content.iter().any(|block| {
                matches!(
                    block,
                    ContentBlock::Text { text }
                        if text.contains("Admitted skill instruction (")
                )
            })
        }));

        let state = turn.into_state().expect("unique turn journal state");
        assert!(
            state.live_hooks().is_empty(),
            "completed typed skill turns leave no active skill hooks"
        );
        assert_eq!(state.skill_events().len(), 1);
    }

    // Catches: moving admitted skill instructions into bounded host context
    // silently drops the final directive of a valid long skill.
    #[test]
    fn long_admitted_skill_keeps_its_final_directive_on_wire() {
        let location =
            ego_core::event::skill::SkillSourceLocation::parse("skills/explain/SKILL.md").unwrap();
        let source_digest = ego_core::event::skill::SkillContentDigest::parse(
            "0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef",
        )
        .unwrap();
        let descriptor = ego_core::event::skill::SkillDescriptorEvidence {
            id: ego_core::event::skill::SkillId::derive(
                ego_core::event::skill::SkillSourceAuthority::User,
                &location,
                "explain",
                &source_digest,
            ),
            name: "explain".into(),
            description: "Explain a request".into(),
            trigger: None,
            argument_hint: None,
            source: ego_core::event::skill::SkillSourceAuthority::User,
            location,
            source_digest,
            user_invocable: true,
            model_invocable: false,
        };
        let final_directive =
            "FINAL DIRECTIVE: report the unresolved evidence before proposing changes.";
        let body = format!(
            "{}\n{final_directive}",
            "Reference material.\n".repeat(4_000)
        );
        let catalogue = Arc::new(
            ego_core::skill::SkillCatalogue::new(vec![
                ego_core::skill::SkillSpec::new(descriptor.clone(), body.into_bytes()).unwrap(),
            ])
            .unwrap(),
        );
        let operation = ego_core::skill::AdmittedSkillOperation::invoke(&descriptor, "");
        let fx = Fixture::new(vec![vec![AiEvent::Stop(StopReason::Stop)]]);
        let skill_evidence = SkillEvidence::new();
        let mut gate = fx.gate.borrow_mut();
        let tools = Tools::from_registry(
            &[RegisteredTool::skill(catalogue)],
            ToolEffectPorts::new(
                &fx.fs,
                fx.process.as_ref(),
                &skill_evidence,
                Arc::new(NoResolver),
                Arc::new(NoHop),
                Arc::new(NoDuplex),
            ),
            CanonPath::new("/ws"),
        );
        let mut turn = TurnLoop::open(
            session(
                SessionState::default(),
                &fx.store,
                &fx.clock,
                &fx.sink,
                CancelToken::new(),
            ),
            model_for(&fx, &fx.generator, &mut gate),
            tools,
        )
        .with_skill_invocation_port(Arc::new(RecordingSkillInvocationPort::default()));
        let outcome = block_on(turn.run_admitted_skill(operation)).unwrap();
        assert!(outcome.ok, "the valid skill was admitted");
        let calls = fx.generator.calls();
        assert_eq!(calls.len(), 1);
        assert!(
            calls[0].messages.messages().iter().any(|message| {
                message.content.iter().any(|block| {
                    matches!(block, ContentBlock::Text { text } if text.contains(final_directive))
                })
            }),
            "admitted skill's final directive was silently truncated before generation"
        );
    }

    #[test]
    fn stale_typed_user_skill_operation_is_refused_before_generation() {
        let location =
            ego_core::event::skill::SkillSourceLocation::parse("skills/explain/SKILL.md")
                .expect("skill source location");
        let old_digest = ego_core::event::skill::SkillContentDigest::parse(
            "0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef",
        )
        .expect("old skill source digest");
        let current_digest = ego_core::event::skill::SkillContentDigest::parse(
            "abcdef0123456789abcdef0123456789abcdef0123456789abcdef0123456789",
        )
        .expect("current skill source digest");
        let old_descriptor = ego_core::event::skill::SkillDescriptorEvidence {
            id: ego_core::event::skill::SkillId::derive(
                ego_core::event::skill::SkillSourceAuthority::User,
                &location,
                "explain",
                &old_digest,
            ),
            name: "explain".to_owned(),
            description: "Explain a request".to_owned(),
            trigger: None,
            argument_hint: None,
            source: ego_core::event::skill::SkillSourceAuthority::User,
            location: location.clone(),
            source_digest: old_digest,
            user_invocable: true,
            model_invocable: false,
        };
        let current_descriptor = ego_core::event::skill::SkillDescriptorEvidence {
            id: ego_core::event::skill::SkillId::derive(
                ego_core::event::skill::SkillSourceAuthority::User,
                &location,
                "explain",
                &current_digest,
            ),
            name: "explain".to_owned(),
            description: "Explain a request".to_owned(),
            trigger: None,
            argument_hint: None,
            source: ego_core::event::skill::SkillSourceAuthority::User,
            location,
            source_digest: current_digest,
            user_invocable: true,
            model_invocable: false,
        };
        assert_ne!(old_descriptor.id, current_descriptor.id);
        let catalogue = Arc::new(
            ego_core::skill::SkillCatalogue::new(vec![
                ego_core::skill::SkillSpec::new(
                    current_descriptor,
                    b"Explain this request: $ARGUMENTS".to_vec(),
                )
                .expect("admitted current skill"),
            ])
            .expect("admitted current catalogue"),
        );
        let operation =
            ego_core::skill::AdmittedSkillOperation::invoke(&old_descriptor, "stale arguments");
        let fx = Fixture::new(vec![]);
        let skill_evidence = SkillEvidence::new();
        let mut gate = fx.gate.borrow_mut();
        let tools = Tools::from_registry(
            &[RegisteredTool::skill(Arc::clone(&catalogue))],
            ToolEffectPorts::new(
                &fx.fs,
                fx.process.as_ref(),
                &skill_evidence,
                Arc::new(NoResolver),
                Arc::new(NoHop),
                Arc::new(NoDuplex),
            ),
            CanonPath::new("/ws"),
        );
        let mut turn = TurnLoop::open(
            session(
                SessionState::default(),
                &fx.store,
                &fx.clock,
                &fx.sink,
                CancelToken::new(),
            ),
            model_for(&fx, &fx.generator, &mut gate),
            tools,
        );

        let _ = block_on(turn.run_admitted_skill(operation));

        assert!(
            fx.generator.calls().is_empty(),
            "a stale operation never contacts the generator"
        );
        assert!(
            !fx.store
                .events()
                .iter()
                .any(|event| matches!(&event.kind, EventKind::SkillInstructionAdmitted { .. }))
        );
    }

    struct ScriptedPolicySource {
        captures: Mutex<VecDeque<Result<GenerationPolicyCapture, String>>>,
        timeline: Arc<Mutex<Vec<String>>>,
        active: Arc<PolicyEngine>,
    }

    impl GenerationPolicySource for ScriptedPolicySource {
        fn current(&self) -> Result<Arc<PolicyEngine>, String> {
            self.timeline.lock().unwrap().push("current".into());
            Ok(Arc::clone(&self.active))
        }

        fn capture(&self) -> Result<GenerationPolicyCapture, String> {
            let next = self
                .captures
                .lock()
                .unwrap()
                .pop_front()
                .expect("one policy capture per generation");
            self.timeline.lock().unwrap().push("capture".into());
            next
        }

        fn restore(
            &self,
            snapshot: Arc<GenerationPolicySnapshot>,
        ) -> Result<GenerationPolicyCapture, String> {
            GenerationPolicyCapture::restore(snapshot, None).map_err(|error| error.to_string())
        }
    }

    fn captured_policy(mode: Mode, rules: Ruleset) -> GenerationPolicyCapture {
        GenerationPolicyCapture::new(CanonPath::new("/ws"), mode, rules, None)
            .expect("valid generation policy capture")
    }

    struct RecordingHookBinding {
        invoker: RecordingHookInvoker,
        policies: Mutex<Vec<Arc<PolicyEngine>>>,
        mcp_bindings: Mutex<usize>,
        fail_at: Option<usize>,
        timeline: Arc<Mutex<Vec<String>>>,
    }

    impl HookInvocationBinding for RecordingHookBinding {
        fn bind<'a>(
            &self,
            policy: Arc<PolicyEngine>,
            _mcp: Option<&dyn McpRuntimeBinding>,
        ) -> Result<Arc<dyn HookInvocationPort + 'a>, String>
        where
            Self: 'a,
        {
            let mut policies = self.policies.lock().unwrap();
            policies.push(Arc::clone(&policy));
            if _mcp.is_some() {
                *self.mcp_bindings.lock().unwrap() += 1;
            }
            self.timeline.lock().unwrap().push("bind".into());
            if self.fail_at == Some(policies.len()) {
                return Err("hook policy binding failed".into());
            }
            Ok(Arc::new(self.invoker.clone()))
        }
    }

    struct TimelineStore<'a> {
        inner: &'a MemStore,
        timeline: Arc<Mutex<Vec<String>>>,
    }

    impl SessionStore for TimelineStore<'_> {
        fn append(&self, id: &SessionId, event: &DomainEvent) -> Result<(), StoreError> {
            self.inner.append(id, event)?;
            match &event.kind {
                EventKind::PermissionDecided { .. } => self
                    .timeline
                    .lock()
                    .unwrap()
                    .push("permission_settled".into()),
                EventKind::ToolCallCompleted { .. } => {
                    self.timeline.lock().unwrap().push("tool_completed".into())
                }
                _ => {}
            }
            Ok(())
        }

        fn compare_and_append_run(
            &self,
            session: &SessionId,
            expected_revision: Option<RunRevision>,
            transaction: RunTransaction,
        ) -> Result<RunAppend, StoreError> {
            self.inner
                .compare_and_append_run(session, expected_revision, transaction)
        }

        fn read(
            &self,
            id: &SessionId,
        ) -> Result<BoxStream<'static, Result<SessionEntry, StoreError>>, StoreError> {
            self.inner.read(id)
        }

        fn list(&self) -> Result<Vec<SessionMeta>, StoreError> {
            self.inner.list()
        }
    }

    #[test]
    fn policy_capture_is_once_per_generation_and_binds_each_tool_batch() {
        let fx = Fixture::new(vec![
            vec![
                AiEvent::ToolCall {
                    call_id: "first".into(),
                    name: "read".into(),
                    args: r#"{"path":"/ws/notes.md"}"#.into(),
                },
                AiEvent::Stop(StopReason::ToolUse),
            ],
            vec![
                AiEvent::ToolCall {
                    call_id: "second".into(),
                    name: "read".into(),
                    args: r#"{"path":"/ws/notes.md"}"#.into(),
                },
                AiEvent::Stop(StopReason::ToolUse),
            ],
            vec![
                AiEvent::TextDelta {
                    text: "done".into(),
                },
                AiEvent::Stop(StopReason::Stop),
            ],
        ])
        .with_read_tool();
        fx.fs.file("/ws/notes.md", "notes");
        let trace = generation_boundary::GenerationTrace::default();
        let timeline = Arc::clone(&trace.timeline);
        let policy_source = Arc::new(ScriptedPolicySource {
            captures: Mutex::new(VecDeque::from([
                Ok(captured_policy(
                    Mode::Default,
                    Ruleset::from_layer(
                        PermCfg {
                            judge: None,
                            allow: vec![Rule::load("read(/ws/notes.md)").unwrap()],
                            deny: vec![],
                        },
                        Source::Project,
                    ),
                )),
                Ok(captured_policy(Mode::Default, Ruleset::default())),
                Ok(captured_policy(Mode::Default, Ruleset::default())),
            ])),
            timeline: Arc::clone(&timeline),
            active: Arc::new(PolicyEngine::new(
                CanonPath::new("/ws"),
                Mode::Default,
                Ruleset::default(),
            )),
        });
        let source = Arc::new(
            generation_boundary::ScriptedGenerationSource::new([
                Ok(generation_boundary::profile(
                    "openai/one",
                    false,
                    vec![
                        AiEvent::ToolCall {
                            call_id: "first".into(),
                            name: "read".into(),
                            args: r#"{"path":"/ws/notes.md"}"#.into(),
                        },
                        AiEvent::Stop(StopReason::ToolUse),
                    ],
                    &trace,
                    Some(2048),
                )),
                Ok(generation_boundary::profile(
                    "openai/two",
                    false,
                    vec![
                        AiEvent::ToolCall {
                            call_id: "second".into(),
                            name: "read".into(),
                            args: r#"{"path":"/ws/missing.md"}"#.into(),
                        },
                        AiEvent::Stop(StopReason::ToolUse),
                    ],
                    &trace,
                    Some(2048),
                )),
                Ok(generation_boundary::profile(
                    "openai/three",
                    false,
                    vec![
                        AiEvent::TextDelta {
                            text: "done".into(),
                        },
                        AiEvent::Stop(StopReason::Stop),
                    ],
                    &trace,
                    Some(2048),
                )),
            ])
            .with_trace(trace.clone()),
        );
        let mut gate = fx.gate.borrow_mut();
        let mut runtime = model_for(&fx, &fx.generator, &mut gate);
        runtime.source = source;
        let timeline_store = TimelineStore {
            inner: &fx.store,
            timeline: Arc::clone(&timeline),
        };
        let tools = Tools::new(
            &fx.registry,
            ToolEffectPorts::new(
                &fx.fs,
                fx.process.as_ref(),
                &fx.evidence,
                Arc::new(NoResolver),
                Arc::new(NoHop),
                Arc::new(NoDuplex),
            ),
            CanonPath::new("/ws"),
        );
        let mut turn = TurnLoop::open(
            session(
                SessionState::default(),
                &timeline_store,
                &fx.clock,
                &fx.sink,
                CancelToken::new(),
            ),
            runtime,
            tools,
        )
        .with_policy_source(policy_source);
        block_on(turn.run("two generations")).expect("turn completes");
        assert_eq!(
            timeline.lock().unwrap().as_slice(),
            [
                "capture",
                "model_resolve",
                "provider",
                "permission_settled",
                "tool_completed",
                "capture",
                "model_resolve",
                "provider",
                "permission_settled",
                "tool_completed",
                "capture",
                "model_resolve",
                "provider",
            ]
        );
        let completed: Vec<bool> = fx
            .store
            .events()
            .iter()
            .filter_map(|event| match event.kind {
                EventKind::ToolCallCompleted { ok, .. } => Some(ok),
                _ => None,
            })
            .collect();
        assert_eq!(completed, [true, false]);
    }

    #[test]
    fn hook_payload_uses_settled_tool_data_and_bounded_ordered_stop_text() {
        struct Capture(Arc<Mutex<Vec<serde_json::Value>>>);
        impl HookInvocationPort for Capture {
            fn invoke<'a>(&'a self, request: HookInvocationRequest) -> HookFuture<'a> {
                self.0.lock().unwrap().push(
                    serde_json::to_value(
                        ego_core::hook::HookHandlerRequestV1::from_runtime(&request).unwrap(),
                    )
                    .unwrap(),
                );
                Box::pin(futures::future::ready(Ok(HookOutcome::new(
                    HookDecision::Continue,
                    None,
                ))))
            }
        }
        let fx = Fixture::new(Vec::new());
        let session = SessionId::new();
        let turn = TurnId::new();
        let journal = SharedJournal::new(Journal::new(
            session,
            &fx.store,
            &fx.clock,
            &fx.sink,
            Producer::Main,
            SessionState::default(),
        ));
        let config = ["SessionStart", "PreToolUse", "PostToolUse", "PostToolUseFailure", "Stop"].iter().map(|event| format!("[[hooks]]\nevent = \"{event}\"\n[hooks.handler]\ntype = \"prompt\"\nprompt = \"capture\"\n")).collect::<String>();
        let catalogue = HookCatalogue::admit_typed(
            &[ConfigLayer::parse(Source::User, &config).unwrap()],
            &[],
            Trust::Trusted,
        )
        .unwrap();
        journal
            .append(
                turn,
                None,
                None,
                EventKind::HookCatalogueAdmitted {
                    descriptors: catalogue.evidence(),
                },
            )
            .unwrap();
        let captured = Arc::new(Mutex::new(Vec::new()));
        let runtime = SessionHookState::new(
            HookLifecycleDispatcher::new(HookRunner::new(), catalogue),
            journal.clone(),
            CancelToken::new(),
            std::time::Instant::now() + std::time::Duration::from_secs(30),
        )
        .with_cwd("/ws".into())
        .bind(Arc::new(Capture(captured.clone())));
        let dispatch = |event: ego_core::hook::HookEvent, causality: HookCausality| {
            let key = ego_core::event::hook::HookOccurrenceKey::new(
                event.lifecycle(),
                causality.owner().clone(),
            );
            block_on(runtime.dispatch(
                Producer::Main,
                ego_core::hook::HookOccurrence::new(key, event, causality).unwrap(),
            ))
            .unwrap()
        };
        assert!(
            !dispatch(
                ego_core::hook::HookEvent::session(HookLifecycle::SessionStart),
                HookCausality::session(session, turn)
            )
            .is_blocked()
        );
        for (ok, response) in [(true, "read content"), (false, "read failed")] {
            let item = ItemId::new();
            let start = journal
                .append(
                    turn,
                    Some(item),
                    None,
                    EventKind::ToolCallStarted {
                        name: "read".into(),
                        args: r#"{"path":"README.md"}"#.into(),
                        call_id: Some(format!("call-{ok}")),
                    },
                )
                .unwrap();
            assert!(
                !dispatch(
                    ego_core::hook::HookEvent::tool(
                        HookLifecycle::PreToolUse,
                        ego_core::event::hook::HookSubject::Item { item },
                        "read(README.md)"
                    ),
                    HookCausality::item(item, turn, start)
                )
                .is_blocked()
            );
            journal
                .append(
                    turn,
                    Some(item),
                    Some(start),
                    EventKind::ToolCallCompleted {
                        ok,
                        result: ToolResult::builtin(response),
                    },
                )
                .unwrap();
            let lifecycle = if ok {
                HookLifecycle::PostToolUse
            } else {
                HookLifecycle::PostToolUseFailure
            };
            dispatch(
                ego_core::hook::HookEvent::tool(
                    lifecycle,
                    ego_core::event::hook::HookSubject::Item { item },
                    "read(README.md)",
                ),
                HookCausality::item(item, turn, start),
            );
        }
        journal
            .append(
                turn,
                Some(ItemId::new()),
                None,
                EventKind::UserPrompt {
                    text: "first prompt".into(),
                    images: Vec::new(),
                    audio: Vec::new(),
                    queued_prompt: None,
                },
            )
            .unwrap();
        let end = journal
            .append(
                turn,
                Some(ItemId::new()),
                None,
                EventKind::AssistantMessage {
                    text: "é".repeat(5000),
                },
            )
            .unwrap();
        dispatch(
            ego_core::hook::HookEvent::turn(
                HookLifecycle::Stop,
                ego_core::event::hook::HookSubject::Turn { turn },
            ),
            HookCausality::generation(ego_core::event::id::GenerationId::new(), turn, end),
        );
        let captured = captured.lock().unwrap();
        assert_eq!(captured.len(), 6);
        for wire in captured.iter() {
            assert_eq!(wire["session_id"], session.to_string());
            assert_eq!(wire["cwd"], "/ws");
        }
        assert_eq!(captured[0]["source"], "startup");
        assert_eq!(captured[1]["tool_name"], "read");
        assert_eq!(captured[1]["tool_input"], json!({"path":"README.md"}));
        assert!(captured[1].get("tool_response").is_none());
        assert_eq!(captured[2]["tool_response"], "read content");
        assert_eq!(captured[4]["error"], "read failed");
        assert!(captured[4].get("tool_response").is_none());
        let transcript = captured[5]["transcript"].as_str().unwrap();
        assert!(transcript.starts_with("UserPrompt: first prompt\nAssistant: é"));
        assert!(transcript.len() <= 8 * 1024);
        assert!(transcript.ends_with("[hook context truncated]"));
    }

    #[test]
    fn hook_context_expiry_is_appended_without_rewriting_prior_observations() {
        struct ContextHook;
        impl HookInvocationPort for ContextHook {
            fn invoke<'a>(&'a self, request: HookInvocationRequest) -> HookFuture<'a> {
                let wire = serde_json::to_value(
                    ego_core::hook::HookHandlerRequestV1::from_runtime(&request).unwrap(),
                )
                .unwrap();
                let decoded: ego_core::hook::HookHandlerRequestV1 =
                    serde_json::from_value(wire.clone()).unwrap();
                assert_eq!(serde_json::to_value(decoded).unwrap(), wire);
                assert_eq!(wire["hook_event_name"], "UserPromptSubmit");
                assert!(wire["session_id"].is_string());
                assert_eq!(wire["cwd"], "/ws");
                let prompt = wire["prompt"].as_str().unwrap();
                let outcome = if prompt == "recall first" {
                    HookOutcome::new(HookDecision::Continue, None)
                        .with_additional_context("context sentinel")
                } else {
                    HookOutcome::new(HookDecision::Continue, None)
                };
                Box::pin(futures::future::ready(Ok(outcome)))
            }
        }
        let fx = Fixture::new(vec![
            vec![AiEvent::Stop(StopReason::Stop)],
            vec![AiEvent::Stop(StopReason::Stop)],
        ]);
        let mut gate = fx.gate.borrow_mut();
        let tools = Tools::new(
            &fx.registry,
            ToolEffectPorts::new(
                &fx.fs,
                fx.process.as_ref(),
                &fx.evidence,
                Arc::new(NoResolver),
                Arc::new(NoHop),
                Arc::new(NoDuplex),
            ),
            CanonPath::new("/ws"),
        );
        let mut turn = TurnLoop::open(
            session(
                SessionState::default(),
                &fx.store,
                &fx.clock,
                &fx.sink,
                CancelToken::new(),
            ),
            model_for(&fx, &fx.generator, &mut gate),
            tools,
        );
        let catalogue = HookCatalogue::admit_typed(&[ConfigLayer::parse(Source::User, "[[hooks]]\nevent = \"UserPromptSubmit\"\n[hooks.handler]\ntype = \"prompt\"\nprompt = \"context\"\n").unwrap()], &[], Trust::Trusted).unwrap();
        turn.journal()
            .append(
                TurnId::new(),
                None,
                None,
                EventKind::HookCatalogueAdmitted {
                    descriptors: catalogue.evidence(),
                },
            )
            .unwrap();
        let state = SessionHookState::new(
            HookLifecycleDispatcher::new(HookRunner::new(), catalogue),
            turn.journal(),
            CancelToken::new(),
            std::time::Instant::now() + std::time::Duration::from_secs(30),
        )
        .with_cwd("/ws".into());
        struct ContextBinding;
        impl HookInvocationBinding for ContextBinding {
            fn bind<'a>(
                &self,
                _policy: Arc<PolicyEngine>,
                _mcp: Option<&dyn McpRuntimeBinding>,
            ) -> Result<Arc<dyn HookInvocationPort + 'a>, String>
            where
                Self: 'a,
            {
                Ok(Arc::new(ContextHook))
            }
        }
        turn = turn
            .with_hook_binding(state, Arc::new(ContextBinding), None)
            .unwrap();
        block_on(turn.run("recall first")).unwrap();
        block_on(turn.run("unrelated second")).unwrap();
        let requests = fx.generator.calls();
        let render = |request: &GenRequest| format!("{:?}", request.messages);
        assert!(render(&requests[0]).contains("context sentinel"));
        assert!(render(&requests[0]).contains("external context data"));
        // Historical evidence remains, but the latest observation expires the context.
        assert_eq!(render(&requests[1]).matches("context sentinel").count(), 1);
        assert!(
            !format!("{:?}", requests[1].messages.messages().last()).contains("context sentinel")
        );
    }

    #[test]
    fn codex_hook_context_preserves_full_previous_request_prefix() {
        // Catches: transient hook context moves behind history on every generation.
        struct ContextHook;
        impl HookInvocationPort for ContextHook {
            fn invoke<'a>(&'a self, request: HookInvocationRequest) -> HookFuture<'a> {
                let wire = serde_json::to_value(
                    ego_core::hook::HookHandlerRequestV1::from_runtime(&request).unwrap(),
                )
                .unwrap();
                let decoded: ego_core::hook::HookHandlerRequestV1 =
                    serde_json::from_value(wire.clone()).unwrap();
                assert_eq!(serde_json::to_value(decoded).unwrap(), wire);
                assert_eq!(wire["hook_event_name"], "UserPromptSubmit");
                assert!(wire["session_id"].is_string());
                assert_eq!(wire["cwd"], "/ws");
                let prompt = wire["prompt"].as_str().unwrap();
                let outcome = if prompt == "recall first" {
                    HookOutcome::new(HookDecision::Continue, None)
                        .with_additional_context("context sentinel")
                } else {
                    HookOutcome::new(HookDecision::Continue, None)
                };
                Box::pin(futures::future::ready(Ok(outcome)))
            }
        }
        let fx = Fixture::new(vec![
            vec![
                AiEvent::ToolCall {
                    call_id: "cache-read".into(),
                    name: "read".into(),
                    args: r#"{"path":"/ws/README.md"}"#.into(),
                },
                AiEvent::Stop(StopReason::ToolUse),
            ],
            vec![
                AiEvent::TextDelta {
                    text: "first answer".into(),
                },
                AiEvent::Stop(StopReason::Stop),
            ],
            vec![
                AiEvent::TextDelta {
                    text: "second answer".into(),
                },
                AiEvent::Stop(StopReason::Stop),
            ],
            vec![
                AiEvent::TextDelta {
                    text: "resumed answer".into(),
                },
                AiEvent::Stop(StopReason::Stop),
            ],
        ])
        .with_read_tool();
        let mut gate = fx.gate.borrow_mut();
        let tools = Tools::new(
            &fx.registry,
            ToolEffectPorts::new(
                &fx.fs,
                fx.process.as_ref(),
                &fx.evidence,
                Arc::new(NoResolver),
                Arc::new(NoHop),
                Arc::new(NoDuplex),
            ),
            CanonPath::new("/ws"),
        );
        let mut runtime = model_for(&fx, &fx.generator, &mut gate);
        runtime.config.system = Some(SystemPrompt::verbatim("stable cache test instructions"));
        let mut turn = TurnLoop::open(
            session(
                SessionState::default(),
                &fx.store,
                &fx.clock,
                &fx.sink,
                CancelToken::new(),
            ),
            runtime,
            tools,
        );
        let catalogue = HookCatalogue::admit_typed(&[ConfigLayer::parse(Source::User, "[[hooks]]\nevent = \"UserPromptSubmit\"\n[hooks.handler]\ntype = \"prompt\"\nprompt = \"context\"\n").unwrap()], &[], Trust::Trusted).unwrap();
        turn.journal()
            .append(
                TurnId::new(),
                None,
                None,
                EventKind::HookCatalogueAdmitted {
                    descriptors: catalogue.evidence(),
                },
            )
            .unwrap();
        let state = SessionHookState::new(
            HookLifecycleDispatcher::new(HookRunner::new(), catalogue),
            turn.journal(),
            CancelToken::new(),
            std::time::Instant::now() + std::time::Duration::from_secs(30),
        )
        .with_cwd("/ws".into());
        struct ContextBinding;
        impl HookInvocationBinding for ContextBinding {
            fn bind<'a>(
                &self,
                _policy: Arc<PolicyEngine>,
                _mcp: Option<&dyn McpRuntimeBinding>,
            ) -> Result<Arc<dyn HookInvocationPort + 'a>, String>
            where
                Self: 'a,
            {
                Ok(Arc::new(ContextHook))
            }
        }
        turn = turn
            .with_hook_binding(state, Arc::new(ContextBinding), None)
            .unwrap();
        block_on(turn.run("recall first")).unwrap();
        block_on(turn.run("unrelated second")).unwrap();
        let id = turn.journal().session_id().unwrap();
        let state = turn.state();
        drop(turn);
        let tools = Tools::new(
            &fx.registry,
            ToolEffectPorts::new(
                &fx.fs,
                fx.process.as_ref(),
                &fx.evidence,
                Arc::new(NoResolver),
                Arc::new(NoHop),
                Arc::new(NoDuplex),
            ),
            CanonPath::new("/ws"),
        );
        let mut runtime = model_for(&fx, &fx.generator, &mut gate);
        runtime.config.system = Some(SystemPrompt::verbatim("stable cache test instructions"));
        let mut resumed = TurnLoop::open(
            Session {
                id,
                ..session(state, &fx.store, &fx.clock, &fx.sink, CancelToken::new())
            },
            runtime,
            tools,
        );
        block_on(resumed.run("resumed third")).unwrap();
        let requests = fx.generator.calls();
        assert_eq!(requests.len(), 4);
        let base = url::Url::parse("https://chatgpt.com/backend-api/").unwrap();
        let target = ego_ai::wire::RequestTarget::new(&base, &[]);
        let captured: Vec<_> = requests
            .iter()
            .map(|request| {
                let wire =
                    ego_ai::wire::openai_codex_responses::build_request(&target, request).unwrap();
                let body = wire.body.unwrap();
                let json: serde_json::Value = serde_json::from_slice(&body).unwrap();
                (body, json, wire.headers)
            })
            .collect();
        assert_eq!(
            captured[0].1["instructions"],
            ego_ai::wire::openai_codex_responses::CODEX_INSTRUCTIONS
        );
        assert_eq!(
            captured[0].1["input"][0]["content"][0]["text"],
            "stable cache test instructions"
        );
        assert!(!captured[0].1["tools"].as_array().unwrap().is_empty());
        for (index, pair) in captured.windows(2).enumerate() {
            let (a_bytes, a, a_headers) = &pair[0];
            let (b_bytes, b, b_headers) = &pair[1];
            if !b["input"]
                .as_array()
                .unwrap()
                .starts_with(a["input"].as_array().unwrap())
            {
                let differing = a_bytes.iter().zip(b_bytes).position(|(a, b)| a != b);
                eprintln!(
                    "Codex capture pair {index}: first differing byte={differing:?}\nfirst={}\nsecond={}",
                    String::from_utf8_lossy(a_bytes),
                    String::from_utf8_lossy(b_bytes)
                );
            }
            for field in ["instructions", "tools", "prompt_cache_key"] {
                assert_eq!(a[field], b[field], "stable {field}");
            }
            for name in ["session-id", "x-client-request-id"] {
                let value = |headers: &[ego_core::permit::HttpHeader]| {
                    headers
                        .iter()
                        .find(|h| h.name() == name)
                        .unwrap()
                        .value()
                        .to_vec()
                };
                assert_eq!(value(a_headers), value(b_headers), "stable {name}");
            }
            let previous = a["input"].as_array().unwrap();
            let next = b["input"].as_array().unwrap();
            // Compare the ordered input bytes, not just item counts or selected fields.
            // A complete JSON document cannot itself be extended after its closing brace.
            let input_bytes = |items: &[serde_json::Value]| {
                items
                    .iter()
                    .flat_map(|item| serde_json::to_vec(item).unwrap())
                    .collect::<Vec<_>>()
            };
            assert!(
                input_bytes(next).starts_with(&input_bytes(previous)),
                "pair {index}: complete prior input bytes must remain a prefix"
            );
        }
    }

    #[test]
    fn policy_capture_failure_has_no_generation_provider_or_effect() {
        let fx = Fixture::new(vec![vec![AiEvent::Stop(StopReason::Stop)]]);
        let trace = generation_boundary::GenerationTrace::default();
        let source = Arc::new(generation_boundary::ScriptedGenerationSource::new([Ok(
            generation_boundary::profile("openai/never", false, vec![], &trace, Some(2048)),
        )]));
        let timeline = Arc::clone(&trace.timeline);
        let policy_source = Arc::new(ScriptedPolicySource {
            captures: Mutex::new(VecDeque::from([Err("poisoned policy".into())])),
            timeline: Arc::clone(&timeline),
            active: Arc::new(PolicyEngine::new(
                CanonPath::new("/ws"),
                Mode::Default,
                Ruleset::default(),
            )),
        });
        let mut gate = fx.gate.borrow_mut();
        let mut runtime = model_for(&fx, &fx.generator, &mut gate);
        runtime.source = source;
        let tools = Tools::new(
            &fx.registry,
            ToolEffectPorts::new(
                &fx.fs,
                fx.process.as_ref(),
                &fx.evidence,
                Arc::new(NoResolver),
                Arc::new(NoHop),
                Arc::new(NoDuplex),
            ),
            CanonPath::new("/ws"),
        );
        let mut turn = TurnLoop::open(
            session(
                SessionState::default(),
                &fx.store,
                &fx.clock,
                &fx.sink,
                CancelToken::new(),
            ),
            runtime,
            tools,
        )
        .with_policy_source(policy_source);
        let outcome = block_on(turn.run("capture fails")).expect("capture refusal is durable");
        assert_eq!(outcome.exit_reason, ExitReason::Internal);
        assert_eq!(timeline.lock().unwrap().as_slice(), ["capture"]);
        assert!(
            fx.store
                .kinds()
                .iter()
                .all(|kind| kind != "generation_started")
        );
        assert!(trace.requests.lock().unwrap().is_empty());
        assert!(
            fx.store
                .kinds()
                .iter()
                .all(|kind| kind != "tool_call_started")
        );
    }

    #[test]
    fn policy_capture_binds_current_prompt_hook_before_generation_capture() {
        let fx = Fixture::new(vec![vec![AiEvent::Stop(StopReason::Stop)]]);
        let trace = generation_boundary::GenerationTrace::default();
        let active = Arc::new(PolicyEngine::new(
            CanonPath::new("/ws"),
            Mode::Auto,
            Ruleset::default(),
        ));
        let captured = captured_policy(Mode::Default, Ruleset::default());
        let captured_policy = captured.policy();
        let policy_source = Arc::new(ScriptedPolicySource {
            captures: Mutex::new(VecDeque::from([Ok(captured)])),
            timeline: Arc::clone(&trace.timeline),
            active: Arc::clone(&active),
        });
        let invoker = Arc::new(RecordingHookInvoker {
            lifecycles: Arc::new(Mutex::new(Vec::new())),
            timeline: Some(Arc::clone(&trace.timeline)),
            block_prompt: false,
            fail_prompt: false,
        });
        let binding = Arc::new(RecordingHookBinding {
            invoker: (*invoker).clone(),
            policies: Mutex::new(Vec::new()),
            mcp_bindings: Mutex::new(0),
            fail_at: None,
            timeline: Arc::clone(&trace.timeline),
        });
        let mut gate = fx.gate.borrow_mut();
        let mut runtime = model_for(&fx, &fx.generator, &mut gate);
        runtime.policy_source = policy_source.clone();
        runtime.source = Arc::new(
            generation_boundary::ScriptedGenerationSource::new([Ok(generation_boundary::profile(
                "openai/hook-binding",
                false,
                vec![AiEvent::Stop(StopReason::Stop)],
                &trace,
                Some(2048),
            ))])
            .with_trace(trace.clone()),
        );
        let tools = Tools::new(
            &fx.registry,
            ToolEffectPorts::new(
                &fx.fs,
                fx.process.as_ref(),
                &fx.evidence,
                Arc::new(NoResolver),
                Arc::new(NoHop),
                Arc::new(NoDuplex),
            ),
            CanonPath::new("/ws"),
        );
        let mut turn = TurnLoop::open(
            session(
                SessionState::default(),
                &fx.store,
                &fx.clock,
                &fx.sink,
                CancelToken::new(),
            ),
            runtime,
            tools,
        );
        let hook_catalogue = HookCatalogue::admit_typed(
            &[ConfigLayer::parse(
                Source::User,
                "[[hooks]]\nevent = \"UserPromptSubmit\"\n[hooks.handler]\ntype = \"prompt\"\nprompt = \"continue\"\n",
            )
            .expect("one prompt hook")],
            &[],
            Trust::Trusted,
        )
        .expect("hook catalogue");
        let state = SessionHookState::new(
            HookLifecycleDispatcher::new(HookRunner::new(), hook_catalogue),
            turn.journal(),
            CancelToken::new(),
            std::time::Instant::now() + std::time::Duration::from_secs(30),
        );
        let mcp = Arc::new(RecordingMcpRuntime::default());
        turn = turn
            .with_hook_binding(state, binding.clone(), Some(mcp.clone()))
            .expect("hook binding attaches to turn");
        let outcome = block_on(turn.run("hook binding")).expect("turn completes");
        assert_eq!(outcome.exit_reason, ExitReason::Completed);
        let policies = binding.policies.lock().unwrap();
        assert_eq!(policies.len(), 2);
        assert!(Arc::ptr_eq(&policies[0], &active));
        assert!(Arc::ptr_eq(&policies[1], &captured_policy));
        assert_eq!(*binding.mcp_bindings.lock().unwrap(), 2);
        assert_eq!(
            mcp.floors.lock().unwrap().as_slice(),
            [active.resume_floor(), captured_policy.resume_floor()]
        );
        assert_eq!(invoker.lifecycles(), vec![HookLifecycle::UserPromptSubmit]);
        assert_eq!(
            trace.timeline.lock().unwrap().as_slice(),
            [
                "current",
                "bind",
                "prompt_hook",
                "capture",
                "bind",
                "model_resolve",
                "provider"
            ]
        );
    }

    #[test]
    fn mcp_runtime_binding_exposes_explicit_pending_policy_recovery_phases() {
        let snapshot = captured_policy(Mode::Default, Ruleset::default()).snapshot();
        let runtime = RecordingMcpRuntime {
            pending_policy: Mutex::new(Some(Arc::clone(&snapshot))),
            ..RecordingMcpRuntime::default()
        };
        let binding: &dyn McpRuntimeBinding = &runtime;

        let loaded = binding
            .load_pending_foreign_policy("continuation")
            .expect("pending policy loads");
        assert!(Arc::ptr_eq(&loaded, &snapshot));

        binding
            .bind_pending_foreign_continuation("continuation", Arc::clone(&loaded))
            .expect("pending continuation binds");
        let bound = runtime.bound_policies.lock().unwrap();
        assert_eq!(bound.len(), 1);
        assert!(Arc::ptr_eq(&bound[0], &snapshot));
    }

