        #[test]
        fn first_mcp_spawn_reaches_normal_permission_admission() {
            // Catches: holding the first spawn instead of applying normal permissions.
            for (name, args) in [
                ("agent", json!({"action":"spawn", "prompt":"Go"})),
                (
                    "agent",
                    json!({"action":"launch", "idempotency_key":"one", "spawn":{"prompt":"Go"}}),
                ),
                (
                    "call_tool",
                    json!({"tool_name":"agent", "arguments":{"action":"spawn", "prompt":"Go"}}),
                ),
                (
                    "call_tool",
                    json!({"tool_name":"agent", "arguments":{"action":"launch", "spawn":{"prompt":"Go"}}}),
                ),
            ] {
                let mut fx = Fixture::new(vec![]);
                fx.registry.push(Arc::new(CapturedSpawnTool(name)));
                let generator = Arc::new(FakeGenerator::new([
                    vec![
                        call("first", name, args),
                        AiEvent::Stop(StopReason::ToolUse),
                    ],
                    vec![AiEvent::Stop(StopReason::Stop)],
                ]));
                let (exit, state) = run_task_host_case(
                    &fx,
                    &generator,
                    CancelToken::new(),
                    None,
                    vec![],
                    vec![],
                    TaskHost {
                        orchestration_guidance: true,
                        ..TaskHost::default()
                    },
                );
                assert_eq!(exit, ExitReason::PermissionRequired, "{name}");
                let calls = generator.calls();
                assert_eq!(
                    calls.len(),
                    1,
                    "{name}: must reach permission on the first call"
                );
                let brief = serde_json::to_string(&calls[0]).unwrap();
                assert!(brief.contains("You are coordinating delegated work for this session."));
                assert!(brief.contains("explicitly tell that agent it is your worker"));
                assert!(brief.contains("explicit completion criteria"));
                assert!(brief.contains("return channel"));
                assert!(
                    brief.contains("concrete recipient"),
                    "an unregistered coordinator alias cannot receive a worker report"
                );
                let first = state
                    .items
                    .values()
                    .find(|item| item.call_id.as_deref() == Some("first"))
                    .unwrap();
                assert_eq!(
                    first.ok,
                    Some(false),
                    "{name}: the original call was denied"
                );
            }
        }

