        #[test]
        fn task_guidance_matches_the_durable_task_contract() {
            // Catches: a host-specific retired bridge displaces the supported durable task API.
            let fx = Fixture::new(vec![]);
            let generator = Arc::new(FakeGenerator::new([vec![AiEvent::Stop(StopReason::Stop)]]));
            run_task_host_case(
                &fx,
                &generator,
                CancelToken::new(),
                None,
                vec![],
                vec![],
                TaskHost {
                    refresh: true,
                    ..TaskHost::default()
                },
            );
            let calls = generator.calls();
            let task = calls[0]
                .tools
                .iter()
                .find(|tool| tool.name == "task")
                .unwrap();
            // Catches: a default native route is presented as a ban on an explicit managed coordinator.
            let override_clause = "Explicit user or applicable workspace instructions may select another available coordination mechanism";
            assert!(task.description.contains(override_clause));
            assert!(calls[0].messages.messages().iter().any(|message| message.role == Role::System && message.content.iter().any(|block| matches!(block, ContentBlock::Text { text } if text.contains(override_clause)))));
            let default_route = "For delegation, use task by default.";
            assert!(task.description.contains(default_route));
            assert!(calls[0].messages.messages().iter().any(|message| message.role == Role::System && message.content.iter().any(|block| matches!(block, ContentBlock::Text { text } if text.contains(default_route)))));
            assert!(!task.description.contains("orchestrator_active"));
        }

        // Catches: stale tracking names or treating waiting/blocked/cancelled work as executable.
        #[test]
        fn worklist_continues_only_actionable_states_at_a_natural_stop() {
            for (status, continuations) in [
                ("pending", 1),
                ("in_progress", 1),
                ("completed", 0),
                ("blocked", 0),
                ("waiting", 0),
                ("cancelled", 0),
            ] {
                let fx = Fixture::new(vec![]);
                let generator = Arc::new(FakeGenerator::new([
                    vec![
                        call(
                            "tracking",
                            "worklist",
                            json!({"operation":"replace","reason":null,"id":null,"status":null, "steps":[
                                {"id":"action", "text":"Perform authorized work", "status":status,"reason":if matches!(status, "waiting" | "blocked") { Some("external dependency") } else { None }}
                            ]}),
                        ),
                        AiEvent::Stop(StopReason::ToolUse),
                    ],
                    vec![AiEvent::Stop(StopReason::Stop)],
                    vec![AiEvent::Stop(StopReason::Stop)],
                ]));
                let (exit, state) = run_tasks(&fx, &generator, CancelToken::new(), None);
                assert_eq!(exit, ExitReason::Completed, "{status}");
                let recorded = fx
                    .store
                    .events()
                    .iter()
                    .filter(|event| matches!(event.kind, EventKind::WorklistContinuation { .. }))
                    .count();
                assert_eq!(recorded, continuations, "{status}");
                assert_eq!(generator.calls().len(), 2 + continuations, "{status}");
                assert_eq!(
                    serde_json::to_value(&state.plan.steps[0]).unwrap()["status"],
                    status
                );
                let descriptors = &generator.calls()[0].tools;
                assert!(descriptors.iter().any(|tool| tool.name == "worklist"));
                assert!(!descriptors.iter().any(|tool| tool.name == "plan"));
            }
        }

        // Catches: one waiting dependency suppresses independent work, or productive work stops early.
        // Catches: model tools invent concurrency, reset started IDs through detours,
        // or use replace/removal to bypass the same journal admission as step.
        #[test]
        fn worklist_dispatch_refuses_fabricated_execution_and_started_regressions_atomically() {
            let fx = Fixture::new(vec![]);
            let requests = [
                (
                    "seed",
                    json!({"operation":"replace","reason":null,"id":null,"status":null,"steps":[
                    {"id":"a","text":"First action","status":"pending","reason":null},
                    {"id":"b","text":"Second action","status":"pending","reason":null}]}),
                ),
                (
                    "start",
                    json!({"operation":"step","reason":null,"steps":null,"id":"a","status":"in_progress"}),
                ),
                (
                    "fake-concurrency",
                    json!({"operation":"step","reason":null,"steps":null,"id":"b","status":"in_progress"}),
                ),
                (
                    "missing-cause",
                    json!({"operation":"step","reason":null,"steps":null,"id":"a","status":"waiting"}),
                ),
                (
                    "suspend",
                    json!({"operation":"step","reason":"waiting for authorized evidence","steps":null,"id":"a","status":"waiting"}),
                ),
                (
                    "reset",
                    json!({"operation":"step","reason":null,"steps":null,"id":"a","status":"pending"}),
                ),
                (
                    "replace-reset",
                    json!({"operation":"replace","reason":null,"id":null,"status":null,"steps":[
                    {"id":"a","text":"First action","status":"pending","reason":null}]}),
                ),
                (
                    "hide-started",
                    json!({"operation":"replace","reason":null,"id":null,"status":null,"steps":[]}),
                ),
                (
                    "finish",
                    json!({"operation":"step","reason":null,"steps":null,"id":"a","status":"completed"}),
                ),
                (
                    "clear",
                    json!({"operation":"replace","reason":null,"id":null,"status":null,"steps":[]}),
                ),
                (
                    "readd",
                    json!({"operation":"replace","reason":null,"id":null,"status":null,"steps":[
                    {"id":"a","text":"First action","status":"pending","reason":null}]}),
                ),
            ];
            let mut scripts = requests
                .iter()
                .map(|(id, args)| {
                    vec![
                        call(id, "worklist", args.clone()),
                        AiEvent::Stop(StopReason::ToolUse),
                    ]
                })
                .collect::<Vec<_>>();
            scripts.push(vec![AiEvent::Stop(StopReason::Stop)]);
            let generator = Arc::new(FakeGenerator::new(scripts));
            let (_, state) = run_tasks(&fx, &generator, CancelToken::new(), None);
            for (id, _) in &requests {
                let item = state
                    .items
                    .values()
                    .find(|item| item.call_id.as_deref() == Some(*id))
                    .unwrap();
                let expected = matches!(*id, "seed" | "start" | "suspend" | "finish" | "clear");
                assert_eq!(item.ok, Some(expected), "{id}: {}", item.text);
            }
            assert!(state.plan.steps.is_empty());
            assert!(state.plan.started.contains("a"));
            assert_eq!(
                fx.store
                    .events()
                    .iter()
                    .filter(|event| matches!(event.kind, EventKind::PlanUpdated { .. }))
                    .count(),
                5,
                "refused requests must not publish plan facts"
            );
        }

