        #[test]
        fn fork_refuses_background_and_named_agents() {
            // Catches: fork silently dropped on a durable or named child.
            let fx = Fixture::new(vec![]);
            let generator = Arc::new(FakeGenerator::new([
                vec![
                    call(
                        "bg",
                        "task",
                        json!({"name":"a", "prompt":"x", "fork":true, "background":true}),
                    ),
                    call(
                        "named",
                        "task",
                        json!({"name":"b", "prompt":"y", "fork":true, "agent":"reviewer"}),
                    ),
                    AiEvent::Stop(StopReason::ToolUse),
                ],
                vec![AiEvent::Stop(StopReason::Stop)],
            ]));
            let (_, state) =
                run_named_tasks(&fx, &generator, CancelToken::new(), None, vec![reviewer()]);
            assert_eq!(generator.calls().len(), 2, "no child generation");
            let mut results: Vec<_> = state
                .items
                .values()
                .filter(|item| item.tool_name.as_deref() == Some("task"))
                .map(|item| (item.ok, tool_result_text(item)))
                .collect();
            results.sort_by(|a, b| a.1.cmp(&b.1));
            assert_eq!(results.len(), 2);
            assert!(results.iter().all(|(ok, _)| *ok == Some(false)));
            assert!(results[0].1.contains("fork does not accept agent"));
            assert!(results[1].1.contains("fork does not accept background"));
        }

        fn reviewer() -> ego_core::turn::NamedAgent {
            ego_core::turn::NamedAgent {
                name: "reviewer".into(),
                prompt: "Review, never modify.".into(),
                model: None,
                effort: None,
                tools: Some(BTreeSet::new()),
                mode: Some(Mode::Plan),
                deny: Vec::new(),
                sandbox: Some(Confinement::Workspace),
                roots: None,
            }
        }

        struct FixtureSearch(Arc<AtomicUsize>);
        impl ego_tools::tools::SearchBackend for FixtureSearch {
            fn prepare(&self, query: &str, _: &PrepareCtx<'_>) -> Result<PreparedCall, ToolError> {
                assert_eq!(query, "child query");
                self.0.fetch_add(1, Ordering::SeqCst);
                Ok(PreparedCall::new(
                    "web_search_external",
                    Op::Read {
                        path: CanonPath::new("/ws/source"),
                    },
                ))
            }
            fn execute<'a, 'io>(
                &'a self,
                _: PreparedCall,
                _: &'a dyn GuardedIo<'io>,
            ) -> BoxFuture<'a, Result<ToolResult, ToolError>>
            where
                'io: 'a,
            {
                Box::pin(async { Ok(ToolResult::builtin("fake Exa source")) })
            }
        }

        #[test]
        fn named_agent_preserves_explicit_search_recipient_on_model_change() {
            // Catches: an unsupported child model gaining external search from a native selector.
            for external in [false, true] {
                let reached = Arc::new(AtomicUsize::new(0));
                let local = Arc::new(Typed(ego_tools::tools::WebSearch::with_backend(Arc::new(
                    FixtureSearch(reached.clone()),
                ))));
                let mut fx = Fixture::new(vec![]);
                fx.registry = vec![ego_tools::tools::selected_web_search(), local];
                let generator = Arc::new(FakeGenerator::new([
                    vec![
                        call(
                            "task1",
                            "task",
                            json!({"name":"lookup", "agent":"reviewer", "prompt":"search"}),
                        ),
                        AiEvent::Stop(StopReason::ToolUse),
                    ],
                    vec![
                        call(
                            "search1",
                            "web_search_external",
                            json!({"query":"child query", "allow_paid":true}),
                        ),
                        AiEvent::Stop(StopReason::ToolUse),
                    ],
                    vec![AiEvent::Stop(StopReason::Stop)],
                    vec![AiEvent::Stop(StopReason::Stop)],
                ]));
                let mut definition = reviewer();
                definition.model = Some(ModelRef("other/fixture".into()));
                definition.mode = None;
                definition.tools = Some(BTreeSet::from([if external {
                    "web_search_external"
                } else {
                    "web_search"
                }
                .into()]));
                let (exit, _) =
                    run_named_tasks(&fx, &generator, CancelToken::new(), None, vec![definition]);
                assert_eq!(exit, ExitReason::Completed);
                let calls = generator.calls();
                assert_eq!(calls[1].model, "other/fixture");
                assert!(calls[1].web_search.is_none());
                assert_eq!(
                    calls[1]
                        .tools
                        .iter()
                        .any(|tool| tool.name == "web_search_external"),
                    external
                );
                assert_eq!(reached.load(Ordering::SeqCst), usize::from(external));
                assert_eq!(
                    format!("{:?}", calls[2].messages).contains("fake Exa source"),
                    external
                );
            }
        }

