        #[test]
        fn named_task_intersects_tools_and_injects_definition_without_child_delegation() {
            // Catches: named tool ceilings only changing the prompt, not executable tools.
            let fx = Fixture::new(vec![]).with_write_tool();
            let generator = Arc::new(FakeGenerator::new([
                vec![
                    call(
                        "task1",
                        "task",
                        json!({"name":"audit", "agent":"reviewer", "prompt":"Inspect"}),
                    ),
                    AiEvent::Stop(StopReason::ToolUse),
                ],
                vec![
                    call(
                        "denied",
                        "fake_write",
                        json!({"path":"/ws/stolen", "contents":"bad"}),
                    ),
                    AiEvent::Stop(StopReason::ToolUse),
                ],
                vec![AiEvent::Stop(StopReason::Stop)],
                vec![AiEvent::Stop(StopReason::Stop)],
            ]));
            let mut definition = reviewer();
            definition.model = Some(ModelRef("test/reviewer".into()));
            let (exit, _) =
                run_named_tasks(&fx, &generator, CancelToken::new(), None, vec![definition]);
            assert_eq!(exit, ExitReason::Completed);
            let calls = generator.calls();
            assert_eq!(calls[1].model, "test/reviewer");
            assert_eq!(calls.last().unwrap().model, calls[0].model);
            assert_ne!(calls[0].model, calls[1].model);
            let task = calls[0]
                .tools
                .iter()
                .find(|tool| tool.name == "task")
                .unwrap();
            assert_eq!(
                task.parameters["properties"]["agent"]["enum"],
                json!(["reviewer"])
            );
            assert!(calls[1].tools.is_empty());
            assert!(format!("{:?}", calls[1].messages).contains("Review, never modify."));
            assert!(fx.fs.read(&CanonPath::new("/ws/stolen")).is_err());
        }

        /// Run one `task` call and return the requests of the parent and the child.
        fn child_selection(
            agent: Option<ego_core::turn::NamedAgent>,
            defaults: ego_core::turn::ChildDefaults,
        ) -> (ThinkingLevel, String, ThinkingLevel, String) {
            let fx = Fixture::new(vec![]);
            let mut args = json!({"name":"audit", "prompt":"Inspect"});
            if let Some(agent) = &agent {
                args["agent"] = json!(agent.name);
            }
            let generator = Arc::new(FakeGenerator::new([
                vec![
                    call("task1", "task", args),
                    AiEvent::Stop(StopReason::ToolUse),
                ],
                vec![AiEvent::Stop(StopReason::Stop)],
                vec![AiEvent::Stop(StopReason::Stop)],
            ]));
            let (exit, _) = run_task_host_case(
                &fx,
                &generator,
                CancelToken::new(),
                None,
                agent.into_iter().collect(),
                vec![],
                TaskHost {
                    child_defaults: defaults,
                    ..TaskHost::default()
                },
            );
            assert_eq!(exit, ExitReason::Completed);
            let calls = generator.calls();
            (
                calls[0].thinking,
                calls[0].model.clone(),
                calls[1].thinking,
                calls[1].model.clone(),
            )
        }

        #[test]
        fn child_effort_and_model_follow_definition_then_default_then_parent() {
            // Catches: a default overriding a definition's own effort or model, a default
            // that never reaches an ordinary task, or a child that ignores effort entirely.
            let defaults = ego_core::turn::ChildDefaults {
                model: Some(ModelRef("test/default-child".into())),
                effort: Some(ThinkingLevel::Low),
            };
            let none = ego_core::turn::ChildDefaults::default();
            let high = ThinkingLevel::High;

            // No default and no definition value: the child inherits the parent.
            let (pt, pm, ct, cm) = child_selection(None, none.clone());
            assert_eq!((ct, cm), (pt, pm.clone()));

            // Default only: an ordinary task and a definition without values both use it.
            let (_, _, ct, cm) = child_selection(None, defaults.clone());
            assert_eq!(
                (ct, cm.as_str()),
                (ThinkingLevel::Low, "test/default-child")
            );
            let (_, _, ct, cm) = child_selection(Some(reviewer()), defaults.clone());
            assert_eq!(
                (ct, cm.as_str()),
                (ThinkingLevel::Low, "test/default-child")
            );

            // Definition values win over the default, field by field.
            let mut definition = reviewer();
            definition.effort = Some(high);
            let (_, _, ct, cm) = child_selection(Some(definition.clone()), defaults.clone());
            assert_eq!((ct, cm.as_str()), (high, "test/default-child"));
            definition.model = Some(ModelRef("test/definition".into()));
            let (_, _, ct, cm) = child_selection(Some(definition), defaults);
            assert_eq!((ct, cm.as_str()), (high, "test/definition"));
        }

        #[test]
        fn task_call_overrides_pin_each_field_and_preserve_parent_requests() {
            // Catches: per-call fields lose to agent/defaults, forks ignore explicit fields,
            // or a child model/effort leaks into the parent's next request.
            for fork in [false, true] {
                for (model, effort) in [
                    (Some("other/child"), Some("low")),
                    (Some("test/child"), None),
                    (None, Some("high")),
                ] {
                    let fx = Fixture::new(vec![]);
                    let mut args = json!({"name":"audit", "prompt":"Inspect", "fork":fork});
                    if let Some(model) = model {
                        args["model"] = json!(model);
                    }
                    if let Some(effort) = effort {
                        args["effort"] = json!(effort);
                    }
                    if !fork {
                        args["agent"] = json!("reviewer");
                    }
                    let generator = Arc::new(FakeGenerator::new([
                        vec![
                            call("task1", "task", args),
                            AiEvent::Stop(StopReason::ToolUse),
                        ],
                        vec![AiEvent::Stop(StopReason::Stop)],
                        vec![AiEvent::Stop(StopReason::Stop)],
                    ]));
                    let mut agent = reviewer();
                    agent.model = Some(ModelRef("test/agent".into()));
                    agent.effort = Some(ThinkingLevel::Medium);
                    let (exit, state) = run_task_host_case(
                        &fx,
                        &generator,
                        CancelToken::new(),
                        None,
                        vec![agent],
                        vec![],
                        TaskHost {
                            child_defaults: ego_core::turn::ChildDefaults {
                                model: Some(ModelRef("test/default".into())),
                                effort: Some(ThinkingLevel::Max),
                            },
                            ..TaskHost::default()
                        },
                    );
                    assert_eq!(exit, ExitReason::Completed);
                    let calls = generator.calls();
                    assert_eq!(calls.len(), 3);
                    let profile = state
                        .task_profiles
                        .values()
                        .next()
                        .expect("actual child profile is retained");
                    assert_eq!(
                        profile.model.0,
                        model.unwrap_or(if fork { "test-model" } else { "test/agent" })
                    );
                    assert_eq!(
                        profile.effort.as_str(),
                        effort.unwrap_or(if fork { "off" } else { "medium" })
                    );
                    assert_eq!(
                        state.execution_profile.as_ref().unwrap().model.0,
                        "test-model"
                    );
                    assert!(fx.sink.events().iter().any(|event| matches!(event, PublicEvent::GenerationProfileSelected { item: Some(_), profile: observed, .. } if observed == profile)));

                    assert_eq!(
                        calls[1].model,
                        model.unwrap_or(if fork { "test-model" } else { "test/agent" })
                    );
                    assert_eq!(
                        calls[1].thinking.as_str(),
                        effort.unwrap_or(if fork { "off" } else { "medium" })
                    );
                    assert_eq!(
                        (calls[2].model.as_str(), calls[2].thinking),
                        ("test-model", ThinkingLevel::Off)
                    );
                    if fork {
                        assert!(
                            format!("{:?}", calls[1].messages).contains("parent"),
                            "fork keeps inherited conversation"
                        );
                    }
                }
            }
        }

